import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    static class SSP {
        int n, source, sink;
        List<List<Integer>> adj;
        static class edge {
            int u, flow, cap, cost, origcost;
        }
        List<edge> edges;
        SSP(int n, int source, int sink) {
            this.n = n;
            this.source = source;
            this.sink = sink;
            this.adj = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                this.adj.add(new ArrayList<>());
            }
            this.edges = new ArrayList<>();
        }
        int add_edge(int a, int b, int cap, int cost) {
            int result = edges.size();
            adj.get(a).add(edges.size());
            edges.add(new edge(b, 0, cap, cost, cost));
            adj.get(b).add(edges.size());
            edges.add(new edge(a, 0, 0, -cost, -cost));
            return result;
        }
        Pair djk() {
            class state_t {
                int dist, prev, maxf;
            }
            PriorityQueue<Pair> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a.first));
            state_t[] states = new state_t[n];
            for (int i = 0; i < n; i++) {
                states[i] = new state_t();
                states[i].dist = Integer.MAX_VALUE / 2;
                states[i].prev = -1;
                states[i].maxf = 0;
            }
            states[source].dist = 0;
            states[source].prev = -2;
            states[source].maxf = Integer.MAX_VALUE;
            pq.add(new Pair(states[source].dist, source));
            while (!pq.isEmpty()) {
                int d, v;
                Pair pair = pq.poll();
                tie(d, v) = pair;
                if (d != states[v].dist) continue;
                for (int edid : adj.get(v)) {
                    edge ed = edges.get(edid);
                    if (ed.flow < ed.cap && states[ed.u].dist > states[v].dist + ed.cost) {
                        states[ed.u].dist = states[v].dist + ed.cost;
                        states[ed.u].prev = edid;
                        states[ed.u].maxf = Math.min(states[v].maxf, ed.cap - ed.flow);
                        pq.add(new Pair(states[ed.u].dist, ed.u));
                    }
                }
            }
            int lastid = states[sink].prev;
            int extraflow = states[sink].maxf;
            int atcost = 0;
            if (lastid == -1) return new Pair(0, 0);
            for (int id = lastid; id != -2; id = states[edges.get(id ^ 1).u].prev) {
                edges.get(id).flow += extraflow;
                edges.get(id ^ 1).flow -= extraflow;
                atcost += edges.get(id).origcost;
            }
            for (int id = 0; id < edges.size(); id++) {
                int v = edges.get(id ^ 1).u;
                int u = edges.get(id).u;
                if (states[v].prev != -1 && states[u].prev != -1)
                    edges.get(id).cost += states[v].dist - states[u].dist;
            }
            return new Pair(extraflow, atcost);
        }
        Pair mfmc() {
            int flow = 0;
            int cost = 0;
            if (edges.stream().anyMatch(ed -> ed.flow > 0 && ed.cost < 0)) bellamanford();
            Pair pair;
            do {
                pair = djk();
                flow += pair.first;
                cost += pair.first * pair.second;
            } while (pair.first > 0);
            return new Pair(flow, cost);
        }
        void bellamanford() {
            int[] dist = new int[n];
            Arrays.fill(dist, Integer.MAX_VALUE / 2);
            dist[source] = 0;
            for (int rep = 0; rep < n; rep++) {
                boolean changed = false;
                for (int id = 0; id < edges.size(); id++) {
                    int v = edges.get(id ^ 1).u;
                    int u = edges.get(id).u;
                    if (edges.get(id).flow < edges.get(id).cap && dist[v] != Integer.MAX_VALUE / 2 && dist[u] > dist[v] + edges.get(id).cost) {
                        dist[u] = dist[v] + edges.get(id).cost;
                        changed = true;
                    }
                }
                if (!changed) break;
            }
            for (int id = 0; id < edges.size(); id++) {
                int v = edges.get(id ^ 1).u;
                int u = edges.get(id).u;
                if (dist[v] < Integer.MAX_VALUE / 2 && dist[u] < Integer.MAX_VALUE / 2)
                    edges.get(id).cost += dist[v] - dist[u];
            }
        }
    }
    static class Pair {
        int first, second;
        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
        @Override
        public String toString() {
            return first + " " + second;
        }
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());
        int max_time = 120;
        int[] a = new int[k];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }
        List<Integer>[] e = new List[n + 1];
        for (int i = 0; i <= n; i++) {
            e[i] = new ArrayList<>();
        }
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            e[x].add(y);
            e[y].add(x);
        }
        int nd = 0;
        int[][] to = new int[max_time][n + 1];
        for (int i = 0; i < max_time; i++) {
            for (int j = 1; j <= n; j++) {
                to[i][j] = nd++;
            }
        }
        int S = nd++;
        int T = nd++;
        SSP flow = new SSP(nd, S, T);
        for (int i = 0; i < k; i++) {
            flow.add_edge(S, to[0][a[i]], 1, 0);
        }
        for (int i = 0; i < max_time; i++) {
            flow.add_edge(to[i][1], T, k, c * i);
        }
        for (int i = 0; i < max_time - 1; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k : e[j]) {
                    for (int z = 0; z <= 52; z++) {
                        flow.add_edge(to[i][j], to[i + 1][k], 1, d * (2 * z + 1));
                    }
                }
                flow.add_edge(to[i][j], to[i + 1][j], k, 0);
            }
        }
        Pair pair = flow.mfmc();
        pw.println(pair.second);
        pw.close();
    }
}

