import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

public class Main {
    static class FlowGraph {
        private int head[], v[], nxt[], c[], ptr, t;
        private long w[], cost;

        private void paddEdge(int uu, int vv, long ww, int cc) {
            v[ptr] = vv;
            w[ptr] = ww;
            c[ptr] = cc;
            nxt[ptr] = head[uu];
            head[uu] = ptr++;
        }

        private int dis[], id[], cur[], vis[];

        private boolean spfa(int s, int t) {
            Arrays.fill(vis, 0);
            Arrays.fill(dis, -1);
            Queue<Integer> q = new ArrayDeque<>();
            q.add(s);
            dis[s] = 0;
            id[s] = 1;
            while (!q.isEmpty()) {
                int nd = q.poll();
                vis[nd] = 0;
                for (int i = head[nd]; i != -1; i = nxt[i]) {
                    if (w[i] > 0 && (dis[v[i]] == -1 || dis[v[i]] > dis[nd] + c[i])) {
                        dis[v[i]] = dis[nd] + c[i];
                        if (!vis[v[i]]) {
                            vis[v[i]] = 1;
                            q.add(v[i]);
                        }
                    }
                }
            }
            return dis[t] != -1;
        }

        private long dfs(int pos, long flow) {
            if (pos == t) return flow;
            vis[pos] = 1;
            long tmp = flow;
            for (int i = cur[pos] != -1 ? cur[pos] : head[pos]; i != -1; i = nxt[i]) {
                if (!vis[v[i]] && w[i] > 0 && dis[v[i]] == dis[pos] + c[i]) {
                    cur[pos] = i;
                    long fl = dfs(v[i], Math.min(flow, w[i]));
                    cost += fl * c[i];
                    w[i] -= fl;
                    w[i ^ 1] += fl;
                    flow -= fl;
                    if (flow == 0) break;
                }
            }
            return tmp - flow;
        }

        public FlowGraph() {
            Arrays.fill(head, -1);
            Arrays.fill(nxt, -1);
        }

        public void addEdge(int uu, int vv, long ww, int cc) {
            paddEdge(uu, vv, ww, cc);
            paddEdge(vv, uu, 0, -cc);
        }

        public long dinic(int s, int t) {
            cost = 0;
            this.t = t;
            while (spfa(s, t)) {
                Arrays.fill(cur, -1);
                dfs(s, Long.MAX_VALUE);
            }
            return cost;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
