        int t = n * 100 + 1;
        for (int i = 1; i <= 100; i++) {
            g.addEdge(i, t, Long.MAX_VALUE, 0);
        }
        for (int i = 1; i <= kk; i++) {
            g.addEdge(s, (a[i] - 1) * 100 + 1, 1, 0);
        }
        for (int i = 2; i <= n; i++) {
            for (int j = 1; j < 100; j++) {
                g.addEdge((i - 1) * 100 + j, (i - 1) * 100 + j + 1, Long.MAX_VALUE, c);
            }
        }
        for (int _ = 1; _ <= m; _++) {
            line = in.readLine().split(" ");
            int t1 = Integer.parseInt(line[0]);
            int t2 = Integer.parseInt(line[1]);
            for (int i = 1; i < 100; i++) {
