import java.io.*;
import java.util.*;

public class Main {
    static final int iinf = 0x3f3f3f3f;
    static final long linf = 0x3f3f3f3f3f3f3f3fL;

    static class Edge {
        int to, flow, cost, rev;

        Edge(int to, int flow, int cost, int rev) {
            this.to = to;
            this.flow = flow;
            this.cost = cost;
            this.rev = rev;
        }
    }

    static class Flow {
        int s, t, fn;
        List<Edge>[] e;
        int[] dep, pre;
        boolean[] vis;
        int[] to, fw, co;

        Flow(int n) {
            s = n * 3 + 1;
            t = s + 1;
            fn = (t + 1);
            e = new List[n * 3 + 2];
            dep = new int[fn];
            pre = new int[fn];
            vis = new boolean[fn];
            to = new int[fn];
            fw = new int[fn];
            co = new int[fn];
            for (int i = 0; i < n * 3 + 2; i++) {
                e[i] = new ArrayList<>();
            }
        }

        void addEdge(int u, int v, int w, int c) {
            e[u].add(new Edge(v, w, c, sz(to)));
            to[sz(to)] = v;
            fw[sz(to)] = w;
            co[sz(to)] = +c;
            e[v].add(new Edge(u, 0, -c, sz(to)));
            to[sz(to)] = u;
            fw[sz(to)] = 0;
            co[sz(to)] = -c;
        }

        boolean spfa() {
            Arrays.fill(dep, iinf);
            Arrays.fill(pre, -1);
            Arrays.fill(vis, false);
            Queue<Integer> q = new LinkedList<>();
            q.add(s);
            vis[s] = true;
            dep[s] = 0;
            while (!q.isEmpty()) {
                int u = q.poll();
                vis[u] = false;
                for (Edge edge : e[u]) {
                    if (fw[edge.rev] > 0 && dep[edge.to] > dep[u] + co[edge.rev]) {
                        dep[edge.to] = dep[u] + co[edge.rev];
                        pre[edge.to] = edge.rev;
                        if (!vis[edge.to]) {
                            q.add(edge.to);
                            vis[edge.to] = true;
                        }
                    }
                }
            }
            return dep[t] < iinf;
        }

        Pair mcmf() {
            Pair res = new Pair(0, 0);
            while (spfa()) {
                int f = iinf;
                for (int u = t; u != s; u = to[pre[u] ^ 1]) {
                    f = Math.min(f, fw[pre[u]]);
                }
                for (int u = t; u != s; u = to[pre[u] ^ 1]) {
                    fw[pre[u]] -= f;
                    fw[pre[u] ^ 1] += f;
                }
                res.x += f;
                res.y += dep[t] * f;
            }
            return res;
        }
    }

    static class Pair {
        int x, y;

        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());
        int mxt = n * 3 + 1;
        Flow flow = new Flow(n * mxt);
        for (int i = 0; i < k; i++) {
            int u = Integer.parseInt(br.readLine()) - 1;
            flow.addEdge(flow.s, u, 1, 0);
        }
        while (m-- > 0) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            for (int i = 0; i < mxt - 1; i++) {
                for (int p = 1; p <= k; p++) {
                    flow.addEdge(i * n + u, (i + 1) * n + v, 1, 2 * d * p - d);
                    flow.addEdge(i * n + v, (i + 1) * n + u, 1, 2 * d * p - d);
                }
            }
        }
        for (int u = 0; u < n; u++) {
            for (int i = 0; i < mxt; i++) {
                flow.addEdge(i * n + u, (i + 1) * n + u, k, 0);
            }
        }
        for (int i = 0; i < mxt; i++) {
            flow.addEdge(i * n + t, i * n + t, k, i * c);
        }
        Pair ans = flow.mcmf();
        pw.println(ans.y);
        pw.close();
    }
}

