public class Main {
    static class edge {
        int from, to, cap, flow, cost;

        edge(int a, int b, int c, int d, int e) {
            from = a;
            to = b;
            cap = c;
            flow = d;
            cost = e;
        }
    }

    static class MCMF {
        int n, m;
        List<edge> e;
        List<Integer>[] g;
        int[] inq;
        int[] d;
        int[] p;
        int[] a;

        void Init(int n) {
            this.n = n;
            for (int i = 0; i <= n; i++)
                g[i].clear();
            e.clear();
        }

        void add(int from, int to, int cap, int cost) {
            e.add(new edge(from, to, cap, 0, cost));
            e.add(new edge(to, from, 0, 0, -cost));
            m = e.size();
            g[from].add(m - 2);
            g[to].add(m - 1);
        }

        boolean bellman(int s, int t, int[] flow, int[] cost) {
            for (int i = 0; i <= t; i++)
                d[i] = Integer.MAX_VALUE;
            inq = new int[n + 1];
            Arrays.fill(inq, 0);
            d[s] = 0;
            inq[s] = 1;
            p = new int[n + 1];
            a = new int[n + 1];
            Arrays.fill(a, Integer.MAX_VALUE);
            Queue<Integer> Q = new LinkedList<>();
            Q.add(s);
            while (!Q.isEmpty()) {
                int u = Q.poll();
                inq[u] = 0;
                for (int i = 0; i < g[u].size(); i++) {
                    edge ee = e.get(g[u].get(i));
                    if (ee.cap > ee.flow && d[ee.to] > d[u] + ee.cost) {
                        d[ee.to] = d[u] + ee.cost;
                        p[ee.to] = g[u].get(i);
                        a[ee.to] = Math.min(a[u], ee.cap - ee.flow);
                        if (!inq[ee.to]) {
                            Q.add(ee.to);
                            inq[ee.to] = 1;
                        }
                    }
                }
            }
            if (d[t] == Integer.MAX_VALUE)
                return false;
            flow[0] += a[t];
            cost[0] += d[t] * a[t];
            int u = t;
            while (u != s) {
                e.get(p[u]).flow += a[t];
                e.get(p[u] ^ 1).flow -= a[t];
                u = e.get(p[u]).from;
            }
            return true;
        }

        int minCost(int s, int t) {
            int flow = 0, cost = 0;
            while (bellman(s, t, new int[]{flow}, new int[]{cost}));
            return cost[0];
        }
    }

    public static void main(String[] args) throws IOException {
