        preve = new int[n + 1];
        inq = new boolean[n + 1];
    }

    static void add_edge(int from, int to, int cap, int cost) {
        G[from].add(new Edge(to, cap, cost, G[to].size()));
        G[to].add(new Edge(from, 0, -cost, G[from].size() - 1));
    }

    static int min_cost_flow(int f) {
        int res = 0;
        while (f > 0) {
            Arrays.fill(dist, inff);
            dist[s] = 0;
            PriorityQueue<Pair> q = new PriorityQueue<>();
