import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    static class Edge {
        int to, flow, cost;
        Edge rev;

        public Edge(int to, int flow, int cost, Edge rev) {
            this.to = to;
            this.flow = flow;
            this.cost = cost;
            this.rev = rev;
        }
    }

    static int N = 10005, M = 2000000, inf = 2000000000;
    static int head[] = new int[N];
    static Edge edges[] = new Edge[M];
    static int cnt = 1;
    static int dis[] = new int[N];
    static boolean mark[] = new boolean[N];

    static void addedge(int x, int y, int flow, int cost) {
        edges[++cnt] = new Edge(y, flow, cost, edges[cnt - 1]);
        edges[cnt - 1].rev = edges[cnt];
        edges[cnt].rev.rev = edges[cnt];
        edges[cnt].to = y;
        edges[cnt].flow = flow;
        edges[cnt].cost = cost;
        edges[cnt - 1].to = x;
        edges[cnt - 1].flow = 0;
        edges[cnt - 1].cost = -cost;
        head[x] = cnt - 1;
    }

    static ArrayDeque<Integer> q = new ArrayDeque<>();

    static boolean spfa() {
        Arrays.fill(mark, false);
        Arrays.fill(dis, inf);
        q.add(N - 1);
        dis[N - 1] = 0;
        mark[N - 1] = true;
        while (!q.isEmpty()) {
            int x = q.poll();
            mark[x] = false;
            for (int i = head[x]; i != -1; i = edges[i].rev.next) {
                int y = edges[i].to;
                if (edges[i].flow > 0 && dis[y] > dis[x] + edges[i].cost) {
                    dis[y] = dis[x] + edges[i].cost;
                    if (!mark[y]) {
                        q.add(y);
                        mark[y] = true;
                    }
                }
            }
        }
        return dis[0] < inf;
    }

    static int dfs(int x, int lim, long cost) {
        int flow = 0;
        mark[x] = true;
        if (x == N - 1) return lim;
        for (int i = head[x]; i != -1; i = edges[i].next) {
            int y = edges[i].to;
            if (edges[i].flow > 0 && dis[x] == dis[y] + edges[i].cost) {
                int t = dfs(y, Math.min(edges[i].flow, lim - flow), cost);
                edges[i].flow -= t;
                edges[i].rev.flow += t;
                flow += t;
                cost += t * edges[i].cost;
                if (flow == lim) return lim;
            }
        }
        return flow;
    }

    static long costflow() {
        int flow = 0;
        long cost = 0;
        while (spfa()) {
            Arrays.fill(mark, false);
            flow += dfs(0, inf, cost);
        }
        return cost;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());
        for (int i = 0; i < k; i++) {
            int x = Integer.parseInt(br.readLine());
            x--;
            addedge(0, x, 1, 0);
        }
        for (int i = 0; i < 101; i++) {
            addedge(i * n, N - 1, k, c * i);
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 100; j++) {
                addedge(i + j * n, i + (j + 1) * n, k, 0);
            }
        }
        while (m-- > 0) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            x--;
            y--;
            for (int i = 0; i < 100; i++) {
                for (int j = k - 1; j >= 0; j--) {
                    addedge(x + i * n, y + (i + 1) * n, 1, d * (j << 1 | 1));
                    addedge(y + i * n, x + (i + 1) * n, 1, d * (j << 1 | 1));
                }
            }
        }
        pw.println(costflow());
        pw.close();
    }
}

