    for(int i=0; i<n; i++) { pot[i] = min(INF, dist[i]+pot[i]); } return df; }
  ll min_cost_flow(int s, int t, ll& price, int n=N, bool sparse=false) {
    //pot_init(n);
		ll flow = price = 0;
		while(ll df=mcf(s, t, price, n, sparse)) { flow += df; } return flow; }
}

