import java.util.Queue;

public class Main {
    static final int maxn = 5000010;
    static final int inf = 1000000000;
    static final int n = 5000000;
    static final int m = 110;
    static final int k = 1000;
    static final int s = 1;
    static final int t = 5000000;

    static int[] head = new int[maxn];
    static int[] dis = new int[maxn];
    static boolean[] vis = new boolean[maxn];
    static int edge_cnt = 1;

    static class Edge {
        int to, nxt, v, c;

        public Edge(int to, int nxt, int v, int c) {
            this.to = to;
            this.nxt = nxt;
            this.v = v;
            this.c = c;
        }
    }

    static Edge[] e = new Edge[maxn];

    static void add(int from, int to, int val, int cost) {
        e[++edge_cnt] = new Edge(to, head[from], val, cost);
        head[from] = edge_cnt;
        e[++edge_cnt] = new Edge(from, head[to], 0, -cost);
        head[to] = edge_cnt;
    }

    static boolean spfa() {
        Queue<Integer> q = new ArrayDeque<>();
        for (int i = s; i <= t; ++i) {
            dis[i] = inf;
            vis[i] = false;
        }
        q.add(s);
        dis[s] = 0;
        vis[s] = true;
        while (!q.isEmpty()) {
            int x = q.poll();
            vis[x] = false;
            for (int i = head[x]; i != 0; i = e[i].nxt) {
                int y = e[i].to;
                int c = e[i].c;
                if (dis[y] <= dis[x] + c || e[i].v == 0) continue;
                dis[y] = dis[x] + c;
                if (!vis[y]) {
                    vis[y] = true;
                    q.add(y);
                }
            }
        }
        return dis[t] != inf;
    }

