            int b = Integer.parseInt(br.readLine().split(" ")[0]);
            for (int j = 1; j <= K + M + 1; j++) {
                for (int k = 1; k <= 2 * K - 1; k += 2) {
                    addEdge(id[a][j], id[b][j + 1], k * D, 1);
                    addEdge(id[b][j], id[a][j + 1], k * D, 1);
                }
            }
        }
        int nn = 0;
        while (spfa()) {
            int aa = -1;
            while (aa != 0) {
                clearFlag();
                aa = dinic(E, Integer.MAX_VALUE);
                nn += aa;
                ans += dis[E] * aa;
            }
        }
