        eg[ect].ne = egh[a];
        egh[a] = ect;
        eg[ect].c = c;
        eg[ect].l = l;
    }

    static boolean spfa() {
        for (int i = 1; i <= pct; i++) {
            flag[i] = false;
            dis[i] = Integer.MAX_VALUE;
        }
        dis[S] = 0;
        q.add(S);
        while (!q.isEmpty()) {
            int p = q.poll();
            flag[p] = false;
            for (int i = egh[p]; i != 0; i = eg[i].ne) {
                if (eg[i].l == 0) continue;
                int b = eg[i].b;
                if (dis[b] > dis[p] + eg[i].c) {
                    dis[b] = dis[p] + eg[i].c;
                    if (!flag[b]) {
                        q.add(b);
                        flag[b] = true;
                    }
                }
            }
        }
        return dis[E] < Integer.MAX_VALUE;
    }

    static int dinic(int x, int y) {
        if (x == S) return y;
        flag[x] = true;
        int tmp = y;
        for (int i = egh[x]; i != 0; i = eg[i].ne) {
            int b = eg[i].b;
            if (flag[b] || eg[i ^ 1].l == 0 || dis[x] < dis[b] + eg[i ^ 1].c) continue;
            int re = dinic(b, Math.min(tmp, eg[i ^ 1].l));
            if (re != 0) {
                tmp -= re;
                eg[i ^ 1].l -= re;
                eg[i].l += re;
                if (tmp == 0) break;
            }
        }
        return y - tmp;
    }

    static void clearFlag() {
        for (int i = 1; i <= pct; i++) {
            flag[i] = false;
        }
