        e[++tot] = new Edge(y, e[y].next, flow, cap);
        e[y].next = tot;
        e[tot].next = e[x].next;
        e[x].next = tot;
        e[tot].to = x;
        e[tot].flow = 0;
        e[tot].cap = cap;
    }

    static boolean bfs() {
        Queue<Integer> q = new LinkedList<>();
        q.add(S);
        dis[S] = 0;
        while (!q.isEmpty()) {
            int now = q.poll();
