    for (int i = 0; i < N; i++)
        for (int t = 0; t < maxT; t++)
            g.add(t * N + i, (t + 1) * N + i, C, K, 0);
    for (int i = 0; i < M; i++)
    {
        int u, v;
        cin >> u >> v;
