import java.util.StringTokenizer;

public class Main {
    static class Pair {
        int first, second;

        public Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    static class Edge {
        int to, next, val, cost;

        public Edge(int to, int next, int val, int cost) {
            this.to = to;
            this.next = next;
            this.val = val;
            this.cost = cost;
        }
    }

    static class MCMF {
        static final int N = 10000, M = 20000000;
        int head[] = new int[N];
        int cnt, dis[] = new int[N], fr[] = new int[N], id[] = new int[N], S, T, cost;

        static Edge edge[] = new Edge[M];

        public void ae(int u, int v, int w, int c) {
            edge[cnt] = new Edge(v, head[u], w, c);
            head[u] = cnt++;
            edge[cnt] = new Edge(u, head[v], 0, -c);
            head[v] = cnt++;
        }

        static ArrayDeque<Integer> q = new ArrayDeque<>();
        static boolean in[] = new boolean[N];

        public boolean SPFA() {
            Arrays.fill(dis, Integer.MAX_VALUE);
            dis[S] = 0;
            q.add(S);
            in[S] = true;
            while (!q.isEmpty()) {
                int x = q.poll();
                in[x] = false;
                for (int i = head[x]; i != -1; i = edge[i].next) {
                    if (edge[i].val == 0) continue;
                    if (dis[edge[i].to] > dis[x] + edge[i].cost) {
                        dis[edge[i].to] = dis[x] + edge[i].cost;
                        fr[edge[i].to] = x;
                        id[edge[i].to] = i;
                        if (!in[edge[i].to]) {
                            in[edge[i].to] = true;
                            q.add(edge[i].to);
                        }
                    }
                }
            }
            if (dis[T] == dis[N - 1]) return false;
            int x = T, mn = Integer.MAX_VALUE;
            while (x != S) mn = Math.min(mn, edge[id[x]].val);
            x = T;
            cost += dis[T] * mn;
            while (x != S) {
                edge[id[x]].val -= mn;
                edge[id[x] ^ 1].val += mn;
                x = fr[x];
            }
            return true;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
