            p[i] = new Pair(Integer.parseInt(st.nextToken()), Integer.parseInt(st.nextToken()));
        }
        for (int i = 0; i < r + n; i++) {
            for (int j = 1; j <= m; j++) {
                for (int k = 1; k <= r; k++) {
                    MCMF.ae(i * n + p[j].first, (i + 1) * n + p[j].second, 1, (2 * k - 1) * d);
