            this.cost = _cost;
            this.rev = _rev;
        }
    }

    static class Min_Cost_Max_Flow {
        int V, H[], dis[], PreV[], PreE[];
        ArrayList<Edge> G[];

        public Min_Cost_Max_Flow(int n) {
            V = n;
            H = new int[n + 5];
            dis = new int[n + 5];
            PreV = new int[n + 5];
            PreE = new int[n + 5];
            G = new ArrayList[n + 5];
            for (int i = 0; i <= n; ++i) G[i] = new ArrayList<>();
        }

        public void add_edge(int from, int to, int cap, int cost) {
            G[from].add(new Edge(to, cap, cost, G[to].size()));
            G[to].add(new Edge(from, 0, -cost, G[from].size() - 1));
        }

        public int minCost(int s, int t, int f) {
            int flow = 0;
            int res = 0;
            for (int i = 0; i <= V; ++i) H[i] = 0;
            while (f > 0) {
                PriorityQueue<pii> q = new PriorityQueue<>((a, b) -> a.first - b.first);
                for (int i = 0; i <= V; ++i) dis[i] = Integer.MAX_VALUE;
                dis[s] = 0; q.add(new pii(0, s));
