public class Main {
    static class Edge {
        int src, dst, rev;
        long flow, cap;
        int cost;
    }

    static class MinCostMaxFlow {
        int n;
        List<List<Edge>> adj;
        int[] potential;
        int[] dist;
        Edge[] back;

        public MinCostMaxFlow(int n) {
            this.n = n;
            adj = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                adj.add(new ArrayList<>());
            }
            potential = new int[n];
            dist = new int[n];
            back = new Edge[n];
        }

        public void addEdge(int src, int dst, long cap, int cost) {
            adj.get(src).add(new Edge(src, dst, adj.get(dst).size(), 0, cap, cost));
            if (src == dst) {
                adj.get(src).get(adj.get(src).size() - 1).rev++;
            }
            adj.get(dst).add(new Edge(dst, src, adj.get(src).size() - 1, 0, 0, -cost));
        }

        public int rcost(Edge e) {
            return e.cost + potential[e.src] - potential[e.dst];
        }

        public int dijkstra(int source, int sink) {
            Arrays.fill(dist, Integer.MAX_VALUE);
            PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
            pq.add(new int[]{dist[source] = 0, source});
            while (!pq.isEmpty()) {
                int[] p = pq.poll();
                if (dist[p[1]] < p[0]) {
                    continue;
                }
                if (p[1] == sink) {
                    break;
                }
                for (Edge e : adj.get(p[1])) {
                    if (e.flow < e.cap && dist[e.dst] > dist[e.src] + rcost(e)) {
                        back[e.dst] = e;
                        pq.add(new int[]{dist[e.dst] = dist[e.src] + rcost(e), e.dst});
                    }
                }
            }
            return dist[sink];
        }

        public long maxFlow(int source, int sink) {
            long flow = 0;
            int cost = 0;
            for (int i = 0; i < n; i++) {
                for (Edge e : adj.get(i)) {
                    e.flow = 0;
                }
            }
            Arrays.fill(potential, 0);
            Arrays.fill(dist, 0);
            Arrays.fill(back, null);
            while (dijkstra(source, sink) < Integer.MAX_VALUE) {
                for (int u = 0; u < n; u++) {
                    if (dist[u] < dist[sink]) {
                        potential[u] += dist[u] - dist[sink];
                    }
                }
                long f = Long.MAX_VALUE;
                for (Edge e = back[sink]; e != null; e = back[e.src]) {
                    f = Math.min(f, e.cap - e.flow);
                }
                for (Edge e = back[sink]; e != null; e = back[e.src]) {
                    e.flow += f;
                    adj.get(e.dst).get(e.rev).flow -= f;
                }
                flow += f;
                cost += f * (potential[sink] - potential[source]);
            }
            return flow;
        }
