    static class Edge {
        int to, f, w;
        Edge next;

        public Edge(int to, int f, int w) {
            this.to = to;
            this.f = f;
            this.w = w;
        }
    }

    static class Node implements Comparable<Node> {
        int u, v;

        public Node(int U, int V) {
            this.u = U;
            this.v = V;
        }

        @Override
        public int compareTo(Node a) {
            return a.v - this.v;
        }
    }

    static class MinCostFlow {
        static int[] dis, tag, cur;
        static boolean[] vis;
        static PriorityQueue<Node> q;

        static int maxf;
        static int minw;

        static void add(int u, int v, int f, int w) {
            Edge e = new Edge(v, f, w);
            e.next = graph[u];
            graph[u] = e;
            Edge e1 = new Edge(u, 0, -w);
            e1.next = graph[v];
            graph[v] = e1;
        }

        static Edge[] graph;

        static void dij(int s, int t) {
            Arrays.fill(dis, Integer.MAX_VALUE);
            Arrays.fill(cur, graph.length);
            dis[t] = 0;
            q.add(new Node(t, 0));
            while (!q.isEmpty()) {
                int u = q.peek().u;
                q.poll();
                if (vis[u]) continue;
                vis[u] = true;
                for (Edge e = graph[u]; e != null; e = e.next) {
                    int v = e.to, w = tag[u] + e.w - tag[v];
                    if (e.f > 0 && dis[u] + w < dis[v]) {
                        dis[v] = dis[u] + w;
                        q.add(new Node(v, dis[v]));
                    }
                }
            }
            for (int i = 0; i < graph.length; i++) {
                tag[i] = Math.min(tag[i] + dis[i], Integer.MAX_VALUE);
            }
            if (!vis[s]) return;
            for (int i = 0; i < graph.length; i++) {
                vis[i] = false;
            }
        }

        static int dfs(int u, int t, int fl) {
            if (u == t || fl == 0) return fl;
            int res = 0;
            vis[u] = true;
            for (Edge e = graph[u]; e != null; e = e.next) {
                if (e.f > 0) {
                    int v = e.to;
                    if (!vis[v] && tag[v] + e.w == tag[u] && (int f = dfs(v, t, Math.min(fl, e.f)))) {
                        e.f -= f;
                        e.next.f += f;
                        res += f;
                        fl -= f;
                        if (fl == 0) break;
                    }
                }
            }
            vis[u] = false;
            return res;
        }

        static void work(int s, int t) {
            while (dij(s, t)) {
                int w = dfs(s, t, Integer.MAX_VALUE);
                maxf += w;
                minw += w * tag[s];
            }
        }
    }

    static int ss, tt, n, m, k, c, d;
    static List<Integer>[] g;

    static int id(int t, int x) {
        return t * n + x + 2;
    }

    static Edge[] edges;

