        int all = n + 2;
        for (int u = 1; u <= n; u++) {
            for (int v : g[u]) {
                for (int p = 1; p <= k; p++) {
                    MinCostFlow.add(id(t, u), id(t + 1, v), 1, d * (2 * p - 1));
                }
