        }
        for (int u = 1; u <= n; u++) {
            MinCostFlow.add(id(t, u), id(t + 1, u), Integer.MAX_VALUE, 0);
        }
        MinCostFlow.add(id(t + 1, 1), tt, Integer.MAX_VALUE, c * (t + 1));
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        c = Integer.parseInt(st.nextToken());
        d = Integer.parseInt(st.nextToken());
        g = new List[n + 1];
        for (int i = 1; i <= n; i++) {
            g[i] = new ArrayList<>();
        }
        for (int i = 1; i <= k; i++) {
            int a = Integer.parseInt(br.readLine());
            MinCostFlow.add(ss, id(0, a), 1, 0);
        }
        for (int i = 1; i <= m; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            g[u].add(v);
            g[v].add(u);
        }
        MinCostFlow.add(id(0, 1), tt, Integer.MAX_VALUE, 0);
        for (int i = 0; i <= n + k; i++) {
            work(i);
        }
        MinCostFlow.work(ss, tt);
        pw.println(MinCostFlow.minw);
        pw.close();
    }
}

