                }
            }
        }
        for (int i = 0; i <= 99; i++) {
            addEdge(0 + i * 50, 5001, Long.MAX_VALUE, c * i);
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 99; j++) {
                addEdge(i + j * 50, i + (j + 1) * 50, Long.MAX_VALUE, 0);
            }
        }
        Pair p = minCostMaxFlow(5000, 5001);
        assert (p.second == k);
        out.println(p.first);
    }

    public static void main(String[] args) {
        solve();
        out.close();
    }

