}

int edmonds_karp(int s, int t) {
	int c, h;

	memcpy(cost_, cost, m_ * sizeof *cost);
	while (1) {
		dijkstra(s);
		if (pi[t] == INF)
			break;
		push(s, t);
		for (h = 0; h < m_; h++) {
			int u = uu[h], v = vv[h];

			if (pi[u] != INF && pi[v] != INF)
				cost_[h] += pi[u] - pi[v];
		}
	}
	c = 0;
	for (h = 0; h < m_; h++)
		c += cost[h] * cc[h << 1 ^ 1];
