        Pair ans = solve(s, t);
        pw.println(ans.second);
        pw.close();
    }

    static void addEdge(int x, int y, int cap, int cost) {
        Edge a = new Edge();
        a.to = y;
        a.cap = cap;
        a.cost = cost;
        a.rev = adj[y].size();
        adj[x].add(a);
        Edge b = new Edge();
        b.to = x;
        b.cap = 0;
        b.cost = -cost;
        b.rev = adj[x].size();
        adj[y].add(b);
    }

    static Pair solve(int s, int t) {
        dist = new int[2 * n + 3];
        prex = new int[2 * n + 3];
        prei = new int[2 * n + 3];
        Arrays.fill(dist, Integer.MAX_VALUE);
        Arrays.fill(prex, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(s);
        dist[s] = 0;
        while (!q.isEmpty()) {
            int x = q.poll();
            for (Edge e : adj[x]) {
                int y = e.to;
                int cc = dist[x] + e.cost;
                if (dist[y] > cc && e.cap > 0) {
                    dist[y] = cc;
                    prex[y] = x;
                    prei[y] = e.rev;
                    if (!adj[y].contains(e.rev)) {
                        adj[y].add(e.rev);
                    }
                    q.add(y);
                }
            }
        }
        tot = 0;
        int ans = 0;
        while (true) {
            for (int i = 0; i < adj.length; i++) {
                adj[i].clear();
            }
            Arrays.fill(dist, Integer.MAX_VALUE);
            Arrays.fill(prex, -1);
            q = new ArrayDeque<>();
            q.add(t);
            dist[t] = 0;
            while (!q.isEmpty()) {
                int x = q.poll();
                for (Edge e : adj[x]) {
                    int y = e.to;
                    int cc = dist[x] + e.cost;
                    if (dist[y] > cc && e.cap > 0) {
                        dist[y] = cc;
                        prex[y] = x;
                        prei[y] = e.rev;
                        if (!adj[y].contains(e.rev)) {
                            adj[y].add(e.rev);
                        }
                        q.add(y);
                    }
                }
            }
            if (dist[t] == Integer.MAX_VALUE) {
                break;
            }
            int f = dfs(t, Integer.MAX_VALUE);
            ans += f;
            tot += f * dist[t];
        }
        return new Pair(ans, tot);
    }

    static int dfs(int x, int flow) {
        if (prex[x] == -1) {
            return flow;
        }
        int y = x;
        x = prex[y];
        int i = prei[y];
        int j = adj[x].get(i).rev;
        int f = dfs(x, Math.min(flow, adj[x].get(i).cap));
        adj[x].get(i).cap -= f;
        adj[y].get(j).cap += f;
        return f;
    }
