public class Main {

    static class Edge {
        int u, v;
        long cap, flow, cost;

        public Edge(int u, int v, long cap, long flow, long cost) {
            this.u = u;
            this.v = v;
            this.cap = cap;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static class MCMF {
        int n, m, s, t;
        ArrayList<Integer>[] G;
        ArrayList<Edge> E;
        long[] d;
        boolean[] inq;
        int[] p;
        long[] a;

        public MCMF(int n) {
            this.n = n;
            G = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                G[i] = new ArrayList<>();
            }
            E = new ArrayList<>();
            d = new long[n];
            inq = new boolean[n];
            p = new int[n];
            a = new long[n];
        }

        public void addEdge(int u, int v, long cap, long cost) {
            E.add(new Edge(u, v, cap, 0, cost));
            E.add(new Edge(v, u, 0, 0, -cost));
            m = E.size();
            G[u].add(m - 2);
            G[v].add(m - 1);
        }

        public boolean BelmanFord(long[] flow, long[] cost) {
            for (int i = 0; i < n; i++) {
                d[i] = Long.MAX_VALUE;
            }
            for (int i = 0; i < n; i++) {
                inq[i] = false;
            }
            d[s] = 0;
            inq[s] = true;
            p[s] = 0;
            a[s] = Long.MAX_VALUE;

            ArrayDeque<Integer> Q = new ArrayDeque<>();
            Q.add(s);
            while (!Q.isEmpty()) {
                int u = Q.poll();
                inq[u] = false;

                for (int i = 0; i < G[u].size(); i++) {
                    Edge e = E.get(G[u].get(i));
                    if (e.cap > e.flow && d[e.v] > d[u] + e.cost) {
                        d[e.v] = d[u] + e.cost;
                        p[e.v] = G[u].get(i);
                        a[e.v] = Math.min(a[u], e.cap - e.flow);

                        if (!inq[e.v]) {
                            Q.add(e.v);
                            inq[e.v] = true;
                        }
                    }
                }
            }

            if (d[t] == Long.MAX_VALUE) {
                return false;
            }
            flow[0] = a[t];
            cost[0] = d[t];
            int u = t;
            while (u != s) {
                E.get(p[u]).flow += a[t];
                E.get(p[u] ^ 1).flow -= a[t];
                u = E.get(p[u]).u;
            }
            return true;
        }

        public long[] Mincost(int s, int t) {
            this.s = s;
            this.t = t;
            long Mcost = 0;
            long Flow = 0;
            long f = 0;
            long d = 0;

            while (BelmanFord(new long[]{f}, new long[]{d})) {
                Flow += f;
                Mcost += f * d;
            }
            return new long[]{Flow, Mcost};
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
