    static ArrayList<Integer>[] g;
    static long ans = 0;
    static long[] dist;
    static int[] pred;
    static int[] pe;
    static int[] inq;

    static int source = N - 2;
    static int target = N - 1;

    static int residualCapacity(int x) {
        return e.get(x).to - e.get(x).f;
    }

    static void dijkstra() {
        for (int i = 0; i < N; i++) {
            dist[i] = Long.MAX_VALUE;
            pred[i] = -1;
            pe[i] = -1;
            inq[i] = 0;
        }
        dist[source] = 0;
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(source);
        inq[source] = 1;
        while (!q.isEmpty()) {
            int k = q.poll();
            inq[k] = 0;
            for (int x : g[k]) {
                if (residualCapacity(x) == 0) {
                    continue;
                }
                int cost = e.get(x).cost;
                int y = e.get(x).from;
                if (dist[y] > dist[k] + cost) {
                    dist[y] = dist[k] + cost;
                    pred[y] = k;
                    pe[y] = x;
                    if (inq[y] == 0) {
                        inq[y] = 1;
                        q.add(y);
                    }
                }
            }
        }
    }

