        pre[t] = -1;
        while (!q.isEmpty()) {
            int x = q.poll();
            vis[x] = false;
            for (int i = h[x][0]; i != 0; i = nex[i][0]) {
                if (val[i][0] != 0 && dis[to[i][0]] > dis[x] + cost[i][0]) {
                    dis[to[i][0]] = dis[x] + cost[i][0];
                    pre[to[i][0]] = x;
                    last[to[i][0]] = i;
                    flow[to[i][0]] = Math.min(flow[x], val[i][0]);
                    if (!vis[to[i][0]]) {
                        vis[to[i][0]] = true;
                        q.add(to[i][0]);
                    }
                }
            }
        }
        return pre[t] != -1;
    }

    static void mcmf() {
        mxf[0] = mnc[0] = 0;
        while (spfa()) {
            int now = t;
            mxf[0] += flow[t];
            mnc[0] += flow[t] * dis[t];
            while (now != s) {
                val[last[now]][0] -= flow[t];
                val[last[now] ^ 1][0] += flow[t];
                now = pre[now];
            }
        }
    }

    static int zh(int t, int x) {
        return t * n + x;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        p = Integer.parseInt(st.nextToken());
        c = Integer.parseInt(st.nextToken());
        d = Integer.parseInt(st.nextToken());
        s = 0;
        t = n * 99 + 1;
        for (int i = 1; i <= p; i++) {
            int x = Integer.parseInt(br.readLine());
            addedge(s, zh(0, x), 1, 0);
            addedge(zh(0, x), s, 0, 0);
        }
        for (int i = 1; i <= m; i++) {
            x[i] = Integer.parseInt(br.readLine().split(" ")[0]);
            y[i] = Integer.parseInt(br.readLine().split(" ")[1]);
        }
        for (int i = 0; i <= 99; i++) {
            addedge(zh(i, 1), zh(i + 1, 1), INF, 0);
            addedge(zh(i + 1, 1), zh(i, 1), 0, 0);
            for (int j = 2; j <= n; j++) {
                addedge(zh(i, j), zh(i + 1, j), INF, c);
                addedge(zh(i + 1, j), zh(i, j), 0, -c);
            }
            for (int j = 1; j <= m; j++) {
                for (int k = 1; k <= p; k++) {
                    int cst = d * k * k - d * (k - 1) * (k - 1) + c;
                    addedge(zh(i, x[j]), zh(i + 1, y[j]), 1, cst);
                    addedge(zh(i + 1, y[j]), zh(i, x[j]), 0, -cst);
                    addedge(zh(i, y[j]), zh(i + 1, x[j]), 1, cst);
                    addedge(zh(i + 1, x[j]), zh(i, y[j]), 0, -cst);
                }
            }
        }
        mcmf();
        System.out.println(mnc[0]);
    }
}

