    static class PrimeNumber {
        int N;
        List<Integer> NP;
        List<Integer> P;
        long _powmod(long a, long b) {
            if (b == 0) return 1;
            if (b % 2 == 1) return a * _powmod(a, b - 1) % MOD;
            return _powmod(a * a % MOD, b / 2);
        }

        public PrimeNumber() {

        }

        public PrimeNumber(int n) {
            N = n;
            NP = new ArrayList<>();
            P = new ArrayList<>();
            for (int i = 2; i * i <= N; i++) {
                if (NP.get(i)) continue;
                for (int j = i * i; j <= N; j += i) {
                    NP.set(j, 1);
                }
            }
            for (int i = 2; i <= N; i++) {
                if (!NP.get(i)) {
                    P.add(i);
                }
            }
        }

        public long gcd(long x, long y) {
            long z;
            while (x > 0) {
                z = y % x;
                y = x;
                x = z;
            }
            return y;
        }

        public long powermod(long p, long q) {
            long g = gcd(p, q);
            p /= g;
            q /= g;
            return p * _powmod(q, MOD - 2) % MOD;
        }

        public List<Integer> factorization(int x) {
            List<Integer> ret = new ArrayList<>();
            int i;
            if (x == 1) {
                ret.add(1);
                return ret;
            }
            ret.add(1);
            ret.add(x);
            for (i = 2; i * i < x; i++) {
                if (x % i == 0) {
                    ret.add(i);
                    ret.add(x / i);
                }
            }
            if (i * i == x) {
                ret.add(i);
            }
            return ret;
        }

        public int factorization2(int x) {
            int ret = 0;
            int i;
            if (x == 1) {
                return 1;
            }
            ret = 2;
            for (i = 2; i * i < x; i++) {
                if (x % i == 0) {
                    ret += 2;
                }
            }
            if (i * i == x) {
                ret++;
            }
            return ret;
        }
    }

