    static class Comb {
        List<List<Long>> C;
        List<Long> F;
        int N;

        public Comb() {

        }

        public Comb(int n) {
            init(n);
        }

        public void init(int n) {
            N = n;
            C = new ArrayList<>();
            for (int i = 0; i <= N; i++) {
                C.add(new ArrayList<>());
            }
            for (int i = 0; i <= N; i++) {
                C.get(i).add(new ArrayList<>());
                C.get(i).add(new ArrayList<>());
                C.get(i).get(0).add(1L);
                C.get(i).get(i).add(1L);
            }
            for (int i = 1; i <= N; i++) {
                for (int j = 1; j < i; j++) {
                    C.get(i).get(j).add((C.get(i - 1).get(j - 1).get(C.get(i - 1).get(j - 1).size() - 1) + C.get(i - 1).get(j).get(C.get(i - 1).get(j).size() - 1)) % MOD;
                }
            }
            F = new ArrayList<>();
            F.add(1L);
            F.add(1L);
            for (int i = 1; i <= N; i++) {
                F.add((F.get(i - 1) * i) % MOD);
            }
        }

        public long getC(int n, int r) {
            return C.get(n).get(r).get(C.get(n).get(r).size() - 1);
        }

        public long getF(int n) {
            return F.get(n);
        }

        public long get_comb(int n, int r) {
            if (n == r || r == 0) return 1;
            if (n <= 1000) return getC(n, r);
            long ret = 1;
            int i;
            if (r > n / 2) {
                r = n - r;
            }
            for (i = n; i > n - r; i--) {
                ret *= i;
            }
            for (i = 2; i <= r; i++) {
                ret /= i;
            }
            return ret;
        }
    }

    static class Sort {
        List<Integer> tmp;
        int N;

        public Sort(int n) {
            N = n;
            tmp = new ArrayList<>();
            tmp.reserve(n + 4);
        }

        public void merge_sort(List<Integer> x, int lo, int hi) {
            if (lo >= hi) return;
            int i, j, k, mid = (lo + hi) / 2;
            merge_sort(x, lo, mid);
            merge_sort(x, mid + 1, hi);
            for (i = lo, j = mid + 1, k = lo; i <= mid && j <= hi; k++) {
                if (x.get(i) < x.get(j)) {
                    tmp.set(k, x.get(i++));
                } else {
                    tmp.set(k, x.get(j++));
                }
            }
            if (i <= mid) {
                for (; i <= mid; i++, k++) {
                    tmp.set(k, x.get(i));
                }
            }
            if (j <= hi) {
                for (; j <= hi; j++, k++) {
                    tmp.set(k, x.get(j));
                }
            }
            for (i = lo; i <= hi; i++) {
                x.set(i, tmp.get(i));
            }
        }
    }

