                ret.add(ret.get(i - 1) + a.get(i));
            }
            return ret;
        }

        public List<List<Integer>> makeSum(List<List<Integer>> a, int n, int m) {
            List<List<Integer>> ret = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                ret.add(new ArrayList<>());
                ret.get(i).add(0);
            }
            for (int i = 0; i < n; i++) {
                for (int j = 1; j < m; j++) {
                    ret.get(i).add(ret.get(i).get(j - 1) + a.get(i).get(j));
                }
            }
            return ret;
        }

        public int getSum(List<Integer> psum, int a, int b) {
            if (a == 0) return psum.get(b);
            return psum.get(b) - psum.get(a - 1);
        }

        public int getSum(List<List<Integer>> psum, int r1, int c1, int r2, int c2) {
            int ret = psum.get(r2).get(c2);
            if (r1 > 0) {
                ret -= psum.get(r1 - 1).get(c2);
            }
            if (c1 > 0) {
                ret -= psum.get(r2).get(c1 - 1);
            }
            if (r1 > 0 && c1 > 0) {
                ret += psum.get(r1 - 1).get(c1 - 1);
            }
            return ret;
        }
