    static class DisjointSet {
        int N;
        List<Integer> P;
        List<Integer> R;
        List<Integer> A;

        public DisjointSet(int n) {
            N = n;
            P = new ArrayList<>();
            R = new ArrayList<>();
            A = new ArrayList<>();
            for (int i = 0; i <= n; i++) {
                P.add(i);
                R.add(0);
                A.add(1);
            }
        }

        public int getA(int x) {
            return A.get(x);
        }

        public int find_set(int x) {
            if (P.get(x).equals(x)) return x;
            int pa = find_set(P.get(x));
            return P.set(x, pa);
        }

        public int union_set(int x, int y) {
            int px, py;
            px = find_set(x);
            py = find_set(y);
            if (px.equals(py)) return px;
            if (R.get(px) > R.get(py)) {
                P.set(py, px);
                A.set(px, A.get(px) + A.get(py));
                return px;
            } else {
                P.set(px, py);
                A.set(py, A.get(py) + A.get(px));
                if (R.get(px).equals(R.get(py))) {
                    R.set(py, R.get(py) + 1);
                }
                return py;
            }
        }
    }

    static class LIS {
        int N;
        int BI;

        public LIS(int n) {
            N = n;
        }

        public int execute(List<Integer> A) {
            List<Integer> v = new ArrayList<>();
            v.add(0);
            int vi = -1;
            for (int i = 1; i < A.size(); i++) {
                if (A.get(i) > v.get(vi)) {
                    v.add(A.get(i));
                    vi++;
                } else {
                    for (int lo = 0, hi = vi; lo < hi; ) {
                        if (v.get((lo + hi) / 2) >= A.get(i)) {
                            hi = (lo + hi) / 2;
                        } else {
                            lo = (lo + hi) / 2 + 1;
                        }
                    }
                    v.set(hi, A.get(i));
                }
            }
            return vi + 1;
        }

        public List<Integer> execute2(List<Integer> A, int &len) {
            List<Integer> v = new ArrayList<>();
            v.add(A.get(0));
            v.add(0);
            List<Integer> p = new ArrayList<>();
            for (int i = 1; i < A.size(); i++) {
                if (v.get(v.size() - 1) < A.get(i)) {
                    p.add(v.get(v.size() - 2));
                    v.add(A.get(i));
                    v.add(i);
                } else {
                    List<Integer> itr = v.subList(0, v.size() - 1);
                    int idx = Collections.binarySearch(itr, A.get(i));
                    if (idx < 0) {
                        idx = -idx - 1;
                    }
                    if (idx != 0) {
                        p.add(v.get(idx - 1));
                    }
                    v.set(idx, A.get(i));
                    v.add(i);
                }
            }
            len = v.size() - 1;
            List<Integer> ret = new ArrayList<>();
            for (int i = v.get(v.size() - 1), j = len - 1; i != -1; i = p.get(i), j--) {
                ret.add(A.get(i));
            }
            return ret;
        }

