            List<Integer> v = new ArrayList<>();
            v.add(0);
            int ret = 0;
            for (int i = 0; i < A.size(); i++) {
                for (int j = 0; j < i; j++) {
                    if (A.get(j) < A.get(i) && v.get(i) < v.get(j)) {
                        v.set(i, v.get(j));
                    }
                }
                v.set(i, v.get(i) + 1);
            }
            for (int i = 0; i < v.size(); i++) {
                if (v.get(i) > ret) {
                    ret = v.get(i);
                }
            }
            return ret;
        }
    }

    static class SegmentTreeSum {
        List<Long> ST;
