            for (int i = 0; i <= n * 4 + 4; i++) {
                ST.add(0L);
            }
            A = new ArrayList<>();
            for (int i = 0; i <= n + 4; i++) {
                A.add(0);
            }
        }

        public long _init(List<Integer> a, int left, int right, int node) {
            if (left == right) {
                return ST.set(node, a.get(left));
            }
            int mid = (left + right) / 2;
            return ST.set(node, _init(a, left, mid, node * 2) + _init(a, mid + 1, right, node * 2 + 1));
        }

        public long _query(int left, int right, int node, int nodeLeft, int nodeRight) {
            if (right < nodeLeft || nodeRight < left) {
                return 0;
            }
            if (left <= nodeLeft && nodeRight <= right) {
                return ST.get(node);
            }
            int mid = (nodeLeft + nodeRight) / 2;
            return _query(left, right, node * 2, nodeLeft, mid) + _query(left, right, node * 2 + 1, mid + 1, nodeRight);
        }

        public long _update(int index, int newValue, int node, int nodeLeft, int nodeRight) {
            if (index < nodeLeft || nodeRight < index) {
                return ST.get(node);
            }
            if (nodeLeft == nodeRight) {
                return ST.set(node, newValue);
            }
            int mid = (nodeLeft + nodeRight) / 2;
            return ST.set(node, _update(index, newValue, node * 2, nodeLeft, mid) + _update(index, newValue, node * 2 + 1, mid + 1, nodeRight));
        }

        public void setA(int x, int y) {
            A.set(x, y);
        }

        public void init() {
            _init(A, 1, N, 1);
        }

        public long query(int left, int right) {
            return _query(left, right, 1, 1, N);
        }

        public long update(int index, int newValue) {
            return _update(index, newValue, 1, 1, N);
        }
