    static class TreeFromExpression {
        public List<Pair> make(char *str, int &root) {
            int i, cur = 1;
            List<Pair> E = new ArrayList<>();
            E.add(new Pair());
            Stack<Integer> S = new Stack<>();
            for (i = 0; str[i]; i++) {
                char cc = str[i];
                if (cc >= '1' && cc <= '9') {
                    E.get(cur).first = cc - '0';
                    E.get(cur).second = 0;
                    S.push(cur);
                    cur++;
                } else if (cc == ')') {
                    int a, b;
                    a = S.pop();
                    b = S.pop();
                    E.get(cur).first = a;
                    E.get(cur).second = b;
                    S.push(cur);
                    cur++;
                }
            }
            root = cur - 1;
            return E;
        }
    }

