            Arrays.fill(dp[c], 0);

            for (int j = 0; j < (1 << n); j++) {
                if (Integer.bitCount(j) != i) continue;

                for (int next : good) {
                    if (((j >> next) & 1) == 0) {
                        dp[c][j ^ (1 << next)] += dp[c ^ 1][j] * p[next] / sum[j];
                    }
                }
            }

            c ^= 1;
        }

