        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        double[] p = new double[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            p[i] = Double.parseDouble(st.nextToken());
        }

        double[] ans = new double[n];
        for (int i = 0; i < n; i++) {
            ans[i] = solve(i, n, k, p);
        }
        for (double d : ans) {
            System.out.printf("%.12f", d);
            if (i + 1 != n) {
                System.out.print(' ');
            } else {
                System.out.println();
            }
            i++;
        }
    }

    public static double solve(int vr, int n, int k, double[] p) {
        if (p[vr] < 1e-9) return 0.0;

        Val[] dp = new Val[1 << n];
        dp[0] = new Val(1.0, 0.0);
        for (int msk = 1; msk < (1 << n); msk++) {
            if ((msk & (1 << vr)) != 0) continue;
            Val ri = new Val(0.0, 0.0);
            double same = 0.0;

            for (int i = 0; i < n; i++) {
                if (i != vr) {
                    if ((msk & (1 << i)) != 0) {
                        same += p[i];
                        ri = add(ri, mult(dp[msk ^ (1 << i)], p[i]));
                    }
                }
            }

            dp[msk] = div(ri, 1.0 - same);
        }

        Val tot = new Val(1.0, 0.0);
        for (int msk = 1; msk < (1 << n); msk++) {
            if ((msk & (1 << vr)) == 0) {
                tot = add(tot, dp[msk]);
            }
        }

        double alp = (1.0 - tot.se) / tot.fi;

        Val bad = new Val(0.0, 0.0);
        for (int msk = 0; msk < (1 << n); msk++) {
            if ((msk & (1 << vr)) != 0) continue;
            if (bits(msk) >= k) {
                bad = add(bad, dp[msk]);
            }
        }

        return 1.0 - (alp * bad.fi + bad.se);
    }

    public static Val add(Val f, Val s) {
        return new Val(f.fi + s.fi, f.se + s.se);
    }

    public static Val sub(Val f, Val s) {
        return new Val(f.fi - s.fi, f.se - s.se);
    }

    public static Val mult(Val f, double w) {
        return new Val(f.fi * w, f.se * w);
    }

    public static Val div(Val f, double w) {
        return new Val(f.fi / w, f.se / w);
    }

    public static int bits(int msk) {
        int count = 0;
        while (msk != 0) {
            count++;
            msk &= msk - 1;
        }
        return count;
    }
}

