    public static long solve(long p, long k) {
        if (k <= 1) return qp(p, p - 1 + k);
        int ord = 1;
        long now = k;
        while (now != 1) {
            now = (now * k) % p;
            ord++;
        }
        return qp(p, (p - 1) / ord);
    }

    public static long qp(long p, long x) {
        long ans = 1;
        for (int i = 0; i < x; i++) {
            ans = (ans * p) % (1e9 + 7);
        }
        return ans;
    }
}

