import java.util.Scanner;

public class Main {
    static final long M = 1000000007;
    static final int N = 1000005;
    static int[] vis = new int[N];

    public static int visit(int x, int k, int p) {
        int cnt = 1;
        vis[x] = 1;
        while (x != 0 && !vis[x % p]) {
            x = (x * k) % p;
            cnt++;
            vis[x % p] = 1;
        }
        return cnt;
    }

    public static long powx(long a, long b, long p) {
        long ans = 1;
        while (b > 0) {
            if ((b & 1) == 1) ans = (ans * a) % p;
            b >>= 1;
            a = (a * a) % p;
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();
        long ans = 1;
        for (int i = 1; i < p; i++) {
            if (vis[i] == 0) {
                long siz = visit(i, k, p);
                long t = powx(k, siz, p);
                if (t != 1 && t != 0) ans = (ans * (siz + 1)) % M;
                else ans = (ans * p) % M;
            }
        }
        if (k == 1) ans = (ans * p) % M;
        System.out.println(ans);
    }
}

