        long ans = 0;
        while (b > 0) {
            if (b % 2 == 1) ans = (ans + a) % Mod;
            b >>= 1;
            a = (a + a) % Mod;
        }
        return ans;
    }

    static long qpow(long a, long b, long Mod) {
        long ans = 1;
        while (b > 0) {
            if (b % 2 == 1) ans = qmul(ans, a, Mod);
            b >>= 1;
            a = qmul(a, a, Mod);
        }
        return ans;
    }

