                    if (dist[e.to] == -1 && e.cap != e.f) {
                        dist[e.to] = dist[n] + 1;
                        q.add(e.to);
                    }
                }
            }
            return dist[t] != -1;
        }

        long aug(int n, long amt, int t) {
            if (n == t) return amt;
            for (; ptr[n] < adj[n].length; ++ptr[n]) {
                Edge e = adj[n][ptr[n]];
                if (dist[e.to] == dist[n] + 1 && e.cap != e.f) {
                    long flow = aug(e.to, Math.min(amt, e.cap - e.f), t);
                    if (flow != 0) {
                        e.f += flow;
                        adj[e.to][e.rev].f -= flow;
                        return flow;
                    }
                }
            }
            return 0;
