        if (lab[r][c] == 'Y') continue;
        if (lab[r][c] == 'Z') {
          z.emplace_back(r, c);
          continue;
        }
        connect(source, g[linear(0, r, c)], lab[r][c] - '0');
        lab[r][c] = '0';
      }
    }
    for (l r = 0; r < n; r++) {
      string row; cin >> row;
      for (l c = 0; c < n; c++) {
        if (row[c] == 'Y' or row[c] == 'Z') continue;
        connect(g[linear(T, r, c)], sink, row[c] - '0');
      }
    }
    const l dr[] = {1, 0, -1, 0};
    const l dc[] = {0, 1, 0, -1};
    for (l t = 0; t < T; t++) {
