              continue;
            connect(g[linear(t, r, c)], g[linear(t + 1, r_, c_)], INF);
          }
        }
      }
      // spread
      vll z_;
      for (auto e : z) {
        l r, c; tie(r, c) = e;
        for (l d = 0; d < 4; d++) {
          l r_ = r + dr[d];
