        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (buf[i][j] == 'Z') {
                    tox[i][j] = 0;
                } else {
                    tox[i][j] = m + 1;
                }
            }
