            if (match(i, e)) cnt++;
        }
        return cnt;
    }

    private boolean match(int x, int[][] e) {
        int[] v = new int[SIZE];
        for (int i = 0; i < e[x].length; i++) {
            int y = e[x][i];
            if (v[y] == 0) v[y] = 1; else continue;
            if (rev[y] < 0 || match(rev[y], e)) {
