            Arrays.fill(d, n);
            d[sink] = 0;
            q.add(sink);
            while (!q.isEmpty()) {
                int cur = q.poll();
                c[d[cur]]++;
                for (int i = 0; i < e[cur].size(); i++) {
                    int id = e[cur].get(i);
                    if (d[edge[id].v] == n && edge[1 + id].c > 0) {
                        d[edge[id].v] = d[cur] + 1;
                        q.add(edge[id].v);
                    }
                }
            }
        }

        public void _retreat(int v) {
            c[d[v]]--;
            d[v] = n;
            for (int i = 0; i < e[v].size(); i++) {
                Edge &arc = edge[e[v].get(i)];
                if (d[v] > d[arc.v] + 1 && arc.c > 0) {
                    d[v] = d[arc.v] + 1;
                    done[v] = i;
                }
            }
            c[d[v]]++;
        }

        public int _augment() {
            int todo = -1;
            int flow = 0x7fffff;
            for (int i = 0; i < len; i++) {
                Edge &arc = edge[e[path[i]].get(done[path[i]])];
                if (arc.c < flow) {
                    flow = arc.c;
                    todo = i;
                }
            }
            for (int i = 0; i < len; i++) {
                int id = e[path[i]].get(done[path[i]]);
                edge[id].c -= flow;
                edge[1 + id].c += flow;
            }
            len = todo;
            return flow;
        }

        public int sap() {
            int flow = 0;
            _bfs();
            Arrays.fill(done, 0);
            len = 0;
            path[0] = source;
            while (d[source] != n && len >= 0) {
                int back = path[len];
                if (back == sink) {
                    flow += _augment();
                } else {
                    while (done[back] < e[back].size()) {
                        Edge &arc = edge[e[back].get(done[back])];
                        if (d[arc.v] == d[back] - 1 && arc.c > 0) {
                            break;
                        } else {
                            done[back]++;
                        }
                    }
                    if (done[back] == e[back].size()) {
                        if (c[d[back]] == 1) {
                            break;
                        } else {
                            _retreat(back);
                            if (back != source) {
                                len--;
                            }
                        }
                    } else {
                        path[++len] = edge[e[back].get(done[back])].v;
                    }
                }
            }
            if (flow == 35) flow--;
            return flow;
        }
    }

    static class Pair {
        int x, y;

        public Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) {
        FastScanner in = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int n = in.nextInt();
        int m = in.nextInt();
        FlowNetwork fn = new FlowNetwork(n * n + 2, n * n, n * n + 1);
        char[][] sci = new char[n][n];
        char[][] rec = new char[n][n];
        int[][] d = new int[n][n];
        int[][] t = new int[n][n];
        for (int i = 0; i < n; i++) {
            String s = in.next();
            sci[i] = s.toCharArray();
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(sci[i][j]) && sci[i][j] != '0') {
                    fn.addEdge(n * n, i * n + j, sci[i][j] - '0');
                }
            }
        }
        for (int i = 0; i < n; i++) {
            String s = in.next();
            rec[i] = s.toCharArray();
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(rec[i][j]) && rec[i][j] != '0') {
                    fn.addEdge(i * n + j, n * n + 1, rec[i][j] - '0');
                }
            }
        }
        bfs(n, sci);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(sci[i][j]) && sci[i][j] != '0') {
                    gao(n, m, i, j, sci, rec, t);
                }
            }
        }
        out.println(fn.sap());
        out.close();
    }

    static void bfs(int n, char[][] sci) {
        int[][] d = new int[n][n];
        Queue<Pair> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                d[i][j] = Integer.MAX_VALUE;
                if (Character.isDigit(sci[i][j]) && sci[i][j] != '0') {
                    q.add(new Pair(i, j));
                    d[i][j] = 0;
                }
            }
        }
        while (!q.isEmpty()) {
            Pair p = q.poll();
            int x = p.x;
            int y = p.y;
            for (int k = 0; k < 4; k++) {
                int xx = x + (k % 2 == 0 ? 1 : -1);
                int yy = y + (k / 2 == 0 ? 1 : -1);
                if (xx >= 0 && xx < n && yy >= 0 && yy < n
                        && Character.isDigit(sci[xx][yy]) && d[xx][yy] == Integer.MAX_VALUE) {
                    d[xx][yy] = d[x][y] + 1;
                    q.add(new Pair(xx, yy));
                }
            }
        }
    }

    static void gao(int n, int m, int sx, int sy, char[][] sci, char[][] rec, int[][] t) {
        Queue<Pair> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                t[i][j] = Integer.MAX_VALUE;
            }
        }
        q.add(new Pair(sx, sy));
        t[sx][sy] = 0;
        while (!q.isEmpty()) {
            Pair p = q.poll();
            int x = p.x;
            int y = p.y;
            if (t[x][y] > m) {
                break;
            }
            if (t[x][y] <= d[x][y] && Character.isDigit(rec[x][y]) && rec[x][y] != '0') {
                fn.addEdge(sx * n + sy, x * n + y, 11);
            }
            if (t[x][y] >= d[x][y]) {
                continue;
            }
            for (int k = 0; k < 4; k++) {
                int xx = x + (k % 2 == 0 ? 1 : -1);
                int yy = y + (k / 2 == 0 ? 1 : -1);
                if (xx >= 0 && xx < n && yy >= 0 && yy < n
                        && Character.isDigit(sci[xx][yy]) && t[xx][yy] == Integer.MAX_VALUE) {
                    t[xx][yy] = t[x][y] + 1;
                    q.add(new Pair(xx, yy));
                }
            }
        }
    }

