        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (S[i][j] > '0' && S[i][j] <= '9') {
                    add(id[i][j] + tot, ed, S[i][j] - '0');
                }
            }
        }
        pw.println(maxflow());
        pw.close();
    }
}

