import java.util.*;

public class Main {
	static class Edge {
		int a, b, cap, flow;
	}

	static Edge[] e;
	static int MAX_NETWORK_NODES = 205;
	static class Pair implements Comparable<Pair> {
		int first, second;
		Pair(int x, int y) {
			first = x;
			second = y;
		}
		public int compareTo(Pair p) {
			return Integer.compare(this.first, p.first);
		}
	}

    public static void addEdge(HashSet<Pair> g, int a, int b, int cap) {
    	Edge e1 = new Edge();
    	e1.a = a;
    	e1.b = b;
    	e1.cap = cap;
    	e1.flow = 0;
    	Edge e2 = new Edge();
    	e2.a = b;
    	e2.b = a;
    	e2.cap = 0;
    	e2.flow = 0;
    	g.add(new Pair(b, (int) e.length));
    	e[(int) e.length] = e1;
    	g.add(new Pair(a, (int) e.length + 1));
    	e[(int) e.length + 1] = e2;
    }

    public static boolean BSF(int v, int s, HashSet<Pair> g, int[] d, int t) {
    	Queue<Integer> q = new LinkedList<>();
    	q.add(s);
    	d[s] = 0;
    	while (!q.isEmpty()) {
    		int x = q.poll();
    		for (Pair it : g) {
    			int id = it.first == x ? it.second : it.first;
    			int to = e[id].b;
    			if(d[to] == -1 && e[id].flow < e[id].cap)
    				q.add(to);
    			if (to == t) return true;
    		}
    	}
    	return false;
    }

    public static int DFS(int v, int s, HashSet<Pair> g, int[] d, int[] ptr, int flow, int t) {
    	if(flow == 0) return 0;
    	if(v == t) return flow;
    	for (; ptr[v] < g.size(); ++ptr[v]) {
    		Pair it = (Pair)g.toArray()[ptr[v]];
    		int id = it.first == v ? it.second : it.first;
    		int to = e[id].b;
    		if (d[to] != d[v] + 1) continue;
    		int pushed = DFS(to, s, g, d, ptr, Math.min(flow, e[id].cap - e[id].flow), t);
    		if (pushed > 0) {
    			e[id].flow += pushed;
    			e[id ^ 1].flow -= pushed;
    			return pushed;
    		}
    	}
    	return 0;
    }

    public static int Dinic() {
    	int flow = 0;
    	int s = 0, t = MAX_NETWORK_NODES - 1;
    	while(BSF(s, s, g[0], d, t)) {
    		Arrays.fill(ptr, 0);
    		while(int pushed = DFS(s, s, g[0], d, ptr, Integer.MAX_VALUE, t))
    			flow += pushed;
    	}
    	return flow;
    }

	public static int get_id(int x, int y) {
	    return x*N+y;
	}

	public static void build_graph(int[][] grid1, int[][] grid2, int[][] grid3, int[][][] B) {
		for(int i=0;i<MAX_NETWORK_NODES;i++) {
			HashSet<Pair> g = new HashSet<>();
			e[i * 2] = new Edge();
			e[i * 2 + 1] = new Edge();
		}
		for(int i=0;i<MAX_NETWORK_NODES;i++) g[i] = new HashSet<Pair>();
	    int N = grid1.length;
	    int[][] A = new int[N][N];
	    int s = 0, t = MAX_NETWORK_NODES - 1;
	    for(int i=0;i<N;i++){
	        for(int j=0;j<N;j++){
	            if (Character.isDigit(grid1[i][j]))
