import java.util.Arrays;
import java.util.List;
import java.util.Queue;

public class Main {

    static class Pos {
        int row, col;

        public Pos(int _row, int _col) {
            row = _row;
            col = _col;
        }
    }

    static int dr[] = {-1, 0, 0, 1};
    static int dc[] = {0, -1, 1, 0};

