    static void add(int u, int v, int w) {
        edges[++cnt] = new Edge();
        edges[cnt].u = u;
        edges[cnt].v = v;
        edges[cnt].flow = 0;
        edges[cnt].cap = w;
        edges[cnt].next = head[u];
        head[u] = cnt;
        edges[++cnt] = new Edge();
        edges[cnt].u = v;
        edges[cnt].v = u;
        edges[cnt].flow = 0;
        edges[cnt].cap = 0;
        edges[cnt].next = head[v];
        head[v] = cnt;
    }

    static boolean find() {
        Queue<Integer> q = new ArrayDeque<>();
        for (int i = 0; i <= t; i++) {
            v[i] = dep[i] = 0;
        }
        q.add(s);
        v[s] = 1;
        dep[s] = 1;
