                }
            }
        }
        for (int i = 1; i <= t; i++) {
            for (int x = 1; x <= n; x++) {
                for (int y = 1; y <= n; y++) {
                    for (int xx = 1; xx <= n; xx++) {
                        for (int yy = 1; yy <= n; yy++) {
                            dp[i][x][y][xx][yy] |= dp[i - 1][x][y][xx][yy];
                        }
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
