    static int INF = 10000000;
    static int N = 210;
    static int M = 21000;
    static Edge[] edge = new Edge[M];
    static int[] adj = new int[M];
    static int[] head = new int[N];
    static int e;

    static void addEdge(int u, int v, int w) {
        edge[e].v = v;
        edge[e].w = w;
        adj[e] = head[u];
        head[u] = e++;
        edge[e].v = u;
        edge[e].w = 0;
        adj[e] = head[v];
        head[v] = e++;
    }

    static int S, T;

    static int[] dist = new int[N];
    static int[] q = new int[N * 2];
    static int[] arc = new int[N];
    static int[] gap = new int[N];
    static int[] inq = new int[N];
    static int[] pre = new int[N];

    static int SAP(int s, int t) {
        Arrays.fill(arc, -1);
        Arrays.fill(pre, -1);
        int qf = 0, qr = 0;
        q[qr++] = t;
        inq[t] = 1;
        gap[0]++;
        dist[t] = 0;
        while (qf < qr) {
            int u = q[qf++];
            for (int i = head[u]; i != -1; i = adj[i]) {
                if (!inq[edge[i].v]) {
                    int v = edge[i].v;
                    q[qr++] = v;
                    inq[v] = 1;
                    dist[v] = dist[u] + 1;
                    gap[dist[v]]++;
                    arc[v] = head[v];
                }
            }
        }
        int low = INF, u = s, ans = 0;
        pre[s] = s;
        while (dist[s] < t) {
            boolean flag = false;
            for (int &i = arc[u]; i != -1; i = adj[i]) {
                if (edge[i].w > 0 && dist[edge[i].v] + 1 == dist[u]) {
                    flag = true;
                    low = Math.min(low, edge[i].w);
                    pre[edge[i].v] = u;
                    u = edge[i].v;
                    if (u == t) {
                        while (u != s) {
                            u = pre[u];
                            edge[arc[u]].w -= low;
                            edge[arc[u] ^ 1].w += low;
                        }
                        ans += low;
                        low = INF;
                    }
                    break;
                }
            }
            if (flag)
                continue;
            int mindis = t + 1;
            for (int i = head[u]; i != -1; i = adj[i]) {
                if (edge[i].w > 0 && mindis > dist[edge[i].v]) {
                    mindis = dist[edge[i].v];
                    arc[u] = i;
                }
            }
            gap[dist[u]]--;
            if (gap[dist[u]] == 0)
                return ans;
            dist[u] = mindis + 1;
            gap[dist[u]]++;
            u = pre[u];
        }
        return ans;
    }

