pair<ll, ll> geta(int x, int y, int b) {
    ll lower = (ll)b * x / y;
    ll upper = ((ll)b * x + (y-1)) / y;
    return {lower, upper};
}

int gcd(int a, int b) {
    if (b == 0) return a;
    return gcd(b, a % b);
