            cands.add(new Fraction(pair.second, b));
        }

        Collections.sort(cands, new Comparator<Fraction>() {
            @Override
            public int compare(Fraction fa, Fraction fb) {
                int a1 = fa.a;
                int b1 = fa.b;
                int a2 = fb.a;
                int b2 = fb.b;

                int left = Math.abs(x * b1 * b2 - a1 * b2 * y);
                int right = Math.abs(x * b1 * b2 - a2 * b1 * y);

                if (left < right) return -1;
                else if (left > right) return 1;

                if (b1 < b2) return -1;
                else if (b1 > b2) return 1;

                if (a1 < a2) return -1;
                return 1;
            }
        });

        System.out.println(cands.get(0).a + "/" + cands.get(0).b);
    }

    public static Pair geta(int x, int y, int b) {
        int lower = (int)(b * x / (double)y);
        int upper = ((int)(b * x + (y-1)) / y);
        return new Pair(lower, upper);
    }

    public static class Fraction {
        public int a, b;

        public Fraction(int a, int b) {
            this.a = a;
            this.b = b;
        }
    }

    public static class Pair {
        public int first, second;

        public Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }
