public class Main {
    static final int mod1 = 998244353, mod2 = (int) 1e9 + 7;
    static final int N = (int) 2e6, MX = (int) 1e6;
    static long n, c;
    static int tot, ans, lim, pw[] = new int[N], sum[] = new int[N];
    static List<Integer> ve[] = new ArrayList[N];

    static int dec(int x, int y, int mod) {
        return (x - y < 0) ? x - y + mod : x - y;
    }

    static int add(int x, int y, int mod) {
        return (x + y >= mod) ? x + y - mod : x + y;
    }

    static void dfs(int pos, int now) {
        if (now <= n) {
            ++tot;
            int x = dec(tot, now, mod1);
            ve[pos - 1].add(x);
            sum[pos - 1] = add(sum[pos - 1], x, mod2);
        }
        if (pos > 6) return;
        for (int i = 0; i <= 9; ++i) dfs(pos + 1, now * 10 + i);
    }

    static void solve(int pos, long now) {
        if (now > n) return;
        if (pos > 1) {
            if (10L * now * MX > n && 1L * (now + 1) * MX - 1 <= n) {
                for (int i = 0; i < 7; ++i) {
                    int x = ((c - 1L * now * pw[i]) % mod1 + mod1) % mod1;
                    int p = Collections.binarySearch(ve[i], mod1 - x);
                    if (p < 0) p = -p - 1;
                    ans = add(ans, add(1L * x * ve[i].size() % mod2, sum[i], mod2), mod2);
                    ans = dec(ans, 1L * mod1 * (ve[i].size() - p) % mod2, mod2);
                }
                c += tot;
                return;
            }
            ++c;
            ans = add(ans, ((c - now) % mod1 + mod1) % mod1, mod2);
        }
        for (int i = (pos == 1 ? 1 : 0); i <= 9; ++i) solve(pos + 1, now * 10 + i);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Long.parseLong(br.readLine());
        pw[0] = 1;
        for (int i = 1; i < 9; ++i) pw[i] = 10 * pw[i - 1];
        dfs(1, 0);
