        for (int i = 0; i <= 9; i++) {
            if (!dep && i == 0) continue;
            dfs2(dep + 1, now * 10 + i);
        }
    }

    static long pow(long x, long y, long mod) {
        long res = 1;
        for (; y > 0; y >>= 1) {
            if (y % 2 > 0) res = res * x % mod;
            x = x * x % mod;
        }
        return res;
    }

