            x = x * 10 + ch - '0';
            ch = br.read();
        }
        return x * f;
    }

    static int lowerBound(long[] arr, long key) {
        int low = 0;
        int high = arr.length;
        while (low < high) {
            int mid = (low + high) / 2;
            if (arr[mid] < key) low = mid + 1;
            else high = mid;
        }
        return low;
    }
