    public static void dfs1(int x, int len, int[][] v, int[] sum) {
        ord++;
        v[len].add((int) ((ord - x + 998244353) % 998244353));
        (sum[len] += v[len][v[len].length - 1]) %= 1000000007;
        if (len == 6) return;
        for (int i = 0; i <= 9; i++) {
            dfs1(x * 10 + i, len + 1, v, sum);
        }
    }

    public static void dfs2(int x, long n, int[][] v, int[] sum, int ord, long ans) {
        if (x > n) return;
        if (x * 1000000 + 1000000 - 1 <= n && x * 10000000 > n) {
            long now = ord;
            for (int i = 0, m = 1; i <= 6; i++, m *= 10) {
                int sz = v[i].length, dt = (int) ((now - x * m) % 998244353);
                int pos = lowerBound(v[i], 998244353 - dt);
                ans = (ans + 1L * dt * sz + sum[i]) % 1000000007;
                ans = (ans - 1L * (sz - pos) * 998244353 % 1000000007 + 1000000007) % 1000000007;
                ord += sz;
            }
            return;
