        ans = (ans + (int) ((ord - x) % 998244353)) % 1000000007;
        for (int i = 0; i <= 9; i++) {
            dfs2(x * 10 + i, n, v, sum, ord, ans);
        }
    }

    public static int lowerBound(int[] arr, int target) {
        int left = 0, right = arr.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

