public class Main {
    static class step implements Comparable<step> {
        long val; int cost;

        public step(long val, int cost) {
            this.val = val;
            this.cost = cost;
        }

        @Override
        public int compareTo(step o) {
            return o.cost - cost;
        }
    }

    static class Scanner {
        BufferedReader br;
        StringTokenizer st;

        public Scanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (Exception e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        PriorityQueue<step> pq = new PriorityQueue<>(Arrays::new Comparator<step>() {
            @Override
            public int compare(step o1, step o2) {
                return o2.cost - o1.cost;
            }
        });

        pq.add(new step(n, 0));
        java.util.HashSet<Long> visited = new java.util.HashSet<>();

        while (pq.peek().val != 0) {
            long val = pq.peek().val;
            int cost = pq.peek().cost;
            pq.poll();

            if (visited.contains(val))
                continue;
            visited.add(val);

            step[] nexts = new step[]{lower(val), upper(val), uupper(val)};
            for (step next : nexts) {
                next.cost += cost;
                next.val = Math.abs(val - next.val);
                pq.add(next);
            }
        }

        System.out.println(pq.peek().cost);
    }

    static step uupper(long n) {
        long res = 0;
        int i = 0;
        while (res < n) {
            res *= 10;
            res++;
            i++;
        }
        return new step(res, i);
