        while (res * 10 + 1 <= n) {
            res *= 10;
            res++;
            i++;
        }
        long resmul = res;
        int imul = i;
        while (res < n) {
            res += resmul;
            i += imul;
        }
        return new step(res, i);
    }

    static step lower(long n) {
        long res = 0;
