        return x;
    }

    public static int smax(int x, int y) {
        if (y > x) {
            x = y;
        }
        return x;
    }

    public static int numof(int x, int n) {
        int ans = 0;
        while (x > 0) {
            ans++;
            x /= 10;
        }
        return ans;
    }

    public static int nxt(int x, int n) {
        int ans[] = new int[17], p = 0;
        while (x > 0) {
            ans[p++] = (x % 10) - (x < 0 ? -1 : 1);
            x /= 10;
        }
        int res = 0;
        while (p-- > 0) {
            res *= 10;
            res += ans[p];
        }
        return res;
    }

    public static int prv(int x, int n) {
        int c = 0, cx = x;
        while (x > 0) {
            c *= 10;
            c += (x < 0 ? -1 : 1);
            x /= 10;
        }
        c *= 10;
        c++;
        return cx - c;
    }

    public static int lst(int x, int n) {
        while (x >= 10) {
            x /= 10;
        }
        return x;
    }

    public static int del(int x, int n) {
        int ans[] = new int[17], p = 0;
        while (x >= 10) {
            ans[p++] = (x % 10);
            x /= 10;
        }
        int res = 0;
        while (p-- > 0) {
            res *= 10;
            res += ans[p];
        }
        return res;
    }

    public static Map<Integer, Integer> mp = new HashMap<>();
}

