            f[i] = f[i - 1] * 10 + 1;
        }
        System.out.print("Enter a number: ");
        long n = scanner.nextLong();
        System.out.println(Solve(n));
    }

    public static int Solve(long x) {
        int res, digits = 15;
        if (x <= 11) return Math.min(x, 13 - x);
        while (f[digits] >= x) --digits;
        res = ((x / f[digits]) * digits) + Solve(x % f[digits]);
        if ((x << 1) < f[digits + 1]) return res;
        return Math.min(res, digits + Solve(f[digits + 1] - x) + 1);
    }
}

