import java.io.*;
import java.util.*;

public class Main {
    static final int mod = 1000000007;
    static final int N = 20;
    static final int MAX = (1 << N);

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int n = Integer.parseInt(br.readLine());
        int[][] a = new int[n][n];
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                a[i][j] = Integer.parseInt(st.nextToken());
                a[i][j] = (int) ((long) a[i][j] * pow(100, mod - 2) % mod);
                a[i][j] = (a[i][j] % mod + mod) % mod;
            }
        }
        if (n == 1) {
            pw.println(a[0][0]);
            pw.close();
            return;
        }
        int m = n / 2;
        long[] cnt = new long[MAX];
        dfs(0, new ArrayList<>(), 1, cnt, a);
        for (int i = 0; i < MAX; i++) {
            cnt[i] %= mod;
        }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < MAX; j++) {
                if (((j >> i) & 1) == 1) {
                    cnt[j] += cnt[j ^ (1 << i)];
                    cnt[j] %= mod;
                }
            }
        }
        long all = cnt[MAX - 1];
        dfs2(m, new ArrayList<>(), 1, cnt, a);
        for (int i = 0; i < MAX; i++) {
            cnt[i] %= mod;
        }
        int[] rev = new int[MAX];
        int nd = 0;
        for (int i = 0; i < MAX; i++) {
            if (Integer.bitCount(i) == m) {
                rev[i] = nd++;
            }
        }
        int[] rev2 = new int[MAX];
        nd = 0;
        int[] cor = new int[MAX];
        for (int i = 0; i < MAX; i++) {
            if (Integer.bitCount(i) == n - m) {
                cor[nd] = rev[MAX - 1 - i];
                rev2[i] = nd++;
            }
        }
        long ans = 0;
        for (int i = 0; i < MAX; i++) {
            long cur = cnt[i];
            int mask = 0;
            for (int j = 0; j < nd; j++) {
                if (((i >> j) & 1) == 1) {
                } else {
                    mask += 1 << cor[j];
                }
            }
            ans += cur * (all - cnt[mask]) % mod;
        }
        pw.println((ans % mod + mod) % mod);
        pw.close();
    }

    static long pow(long x, long n) {
        long res = 1;
        while (n > 0) {
            if (n % 2 == 1) {
                res = res * x % mod;
            }
            x = x * x % mod;
            n >>= 1;
        }
        return res;
    }

    static void dfs(int cur, List<Integer> con, long prob, long[] cnt, int[][] a) {
        if (cur == m) {
            int nxt = 0, id = 0;
            for (int j = 0; j < (1 << n); j++) {
                if (Integer.bitCount(j) != m) {
                    continue;
                }
                List<Integer> vi = new ArrayList<>();
                for (int i = 0; i < n; i++) {
                    if (((j >> i) & 1) == 1) {
                        vi.add(i);
                    }
                }
                int ok = 0;
                do {
                    for (int x = 0; x < m; x++) {
                        if (((con.get(x) >> vi.get(x)) & 1) == 0) {
                            break;
                        }
                    }
                    if (x == m) {
                        ok = 1;
                        break;
                    }
                } while (nextPermutation(vi));
                if (ok) {
                    id |= 1 << nxt;
                }
                nxt++;
            }
            cnt[id] += prob;
            return;
        }
        for (int j = 0; j < (1 << n); j++) {
            con.add(j);
            long nw = prob;
            for (int k = 0; k < n; k++) {
                if (((j >> k) & 1) == 1) {
                    nw = nw * a[cur][k] % mod;
                } else {
                    nw = nw * (mod + 1 - a[cur][k]) % mod;
                }
            }
            dfs(cur + 1, con, nw, cnt, a);
            con.remove(con.size() - 1);
        }
    }

    static void dfs2(int cur, List<Integer> con, long prob, long[] cnt, int[][] a) {
        if (cur == n) {
            int nxt = 0, id = 0;
            for (int j = 0; j < (1 << n); j++) {
                if (Integer.bitCount(j) != n - m) {
                    continue;
