public class Main {
    static final int MOD = 1000000007;
    static int modpow(int a, int e) {
        int ret = 1;
        while (e > 0) {
            if (e % 2 == 1) ret = (ret * a) % MOD;
            a = (a * a) % MOD;
            e >>= 1;
        }
        return ret;
    }

    static int pr[][] = new int[6][6];
    static int sub[][] = new int[2][1 << 18];
    static int mas[] = new int[1 << 18];
    static int p[][] = new int[2][1 << 20];
    static List<Integer> m3 = new ArrayList<>();
    static int comp[] = new int[20];

    static int cm(int a) {
        int ret = 0;
        for (int i = 0; i < 20; i++) {
            if ((a & (1 << i)) != 0) ret += (1 << comp[i]);
        }
        return ret;
    }

