        Scanner sc = new Scanner(System.in);
        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 1; i < (1 << 6); i++) {
            if (Integer.bitCount(i) == 3) {
                m3.add(i);
                map.put(i, m3.size() - 1);
            }
        }
        for (int i = 1; i < (1 << 6); i++) {
            if (Integer.bitCount(i) == 3) {
                comp[map.get(i)] = map.get(i ^ (1 << 63));
            }
        }
        assert map.size() == 20;
        int n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                pr[i][j] = sc.nextInt();
                pr[i][j] = (int) ((long) pr[i][j] * modpow(100, MOD - 2) % MOD);
            }
        }
        for (int i = n; i < 6; i++) {
            pr[i][i] = 1;
        }
        n = 6;
        for (int mask = 0; mask < (1 << 18); mask++) {
            sub[0][mask] = 1;
            sub[1][mask] = 1;
            for (int i = 0; i < 6; i++) {
                for (int j = 0; j < 3; j++) {
                    if ((mask & (1 << ((i * 3) + j))) != 0) {
                        sub[0][mask] = (int) ((long) sub[0][mask] * pr[i][j] % MOD);
                        sub[1][mask] = (int) ((long) sub[1][mask] * pr[i][3 + j] % MOD);
                    } else {
