                        if (od < 0) od += MOD;
                        sub[0][mask] = (int) ((long) sub[0][mask] * od % MOD);
                        od = 1 - pr[i][3 + j];
                        if (od < 0) od += MOD;
                        sub[1][mask] = (int) ((long) sub[1][mask] * od % MOD);
                    }
                }
            }
            int ind = 0;
            for (int m : m3) {
                List<Integer> guys = new ArrayList<>();
                for (int i = 0; i < 6; i++) {
                    if ((m & (1 << i)) != 0) guys.add(i);
                }
                boolean bad = false;
                for (int xd = 0; xd < (1 << 3); xd++) {
                    int ms = 0;
                    for (int i = 0; i < 3; i++) {
                        if ((xd & (1 << i)) != 0) ms |= (mask >> (guys.get(i) * 3)) & 7;
