        for (int i = 0; i < (1 << 18); i++) {
            p[0][mas[i]] = (p[0][mas[i]] + sub[0][i]) % MOD;
        }
        for (int i = 0; i < (1 << 18); i++) {
            p[1][cm(mas[i])] = (p[1][cm(mas[i])] + sub[1][i]) % MOD;
