        while (b > 0) {
            if ((b & 1) == 1) {
                times = (times * a) % MOD;
            }
            a = (a * a) % MOD;
            b >>= 1;
        }
        return times;
    }

    static Map<Bitset, Integer> id = new HashMap<>();
    static int N, cnt;
    static int[][] P = new int[7][7];
    static int[][] dp = new int[2][MAX];
    static int[][] trans = new int[MAX][MAXN];
    static int[] prob = new int[MAXN];
    static int iv100;

    static int dfs(Bitset x) {
        if (id.containsKey(x)) {
            return id.get(x);
        }
        int nd = id.size();
        id.put(x, nd);
        Bitset tmp[] = new Bitset[7];
        for (int i = 0; i < N; i++) {
            tmp[i] = new Bitset(MAXN);
            for (int j = 0; j < MAXN; j++) {
                tmp[i].set(j | (1 << i));
            }
        }
        for (int i = 0; i < MAXN; i++) {
            Bitset tp = new Bitset(MAXN);
            tp.or(x);
            for (int j = 0; j < N; j++) {
                if ((i >> j & 1) == 1) {
                    tp.or(tmp[j]);
                }
            }
            trans[nd][i] = dfs(tp);
        }
        return nd;
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        N = scanner.nextInt();
        Bitset tmp = new Bitset(MAXN);
        tmp.set(0);
        dfs(tmp);
        iv100 = (int) poww(100, MOD - 2);
        out.println(id.size());
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                P[i][j] = scanner.nextInt();
            }
        }
        dp[0][1] = 1;
        int x = 0;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < MAXN; j++) {
                prob[j] = 1;
                for (int k = 0; k < N; k++) {
                    prob[j] = (int) ((long) prob[j] * iv100 % MOD * (j >> k & 1 ? P[i][k] : 100 - P[i][k]) % MOD);
                }
            }
            for (int j = 0; j < 2; j++) {
                for (int k = 1; k <= id.size(); k++) {
                    if (dp[j][k] != 0) {
                        for (int l = 0; l < MAXN; l++) {
                            dp[j ^ 1][trans[k][l]] = (dp[j ^ 1][trans[k][l]] + (int) (dp[j][k] * prob[l])) % MOD;
                        }
                    }
                }
            }
        }
        Bitset tmp2 = new Bitset(MAXN);
        for (int i = 0; i < MAXN; i++) {
            tmp2.set(i);
        }
        out.println(dp[x][id.get(tmp2)]);
        out.close();
    }
}

