import java.io.*;
import java.util.*;

public class Main {
    static class ModInt {
        static final long MOD = (long) Math.pow(10, 9) + 7;
        long v;

        ModInt(long _v) {
            v = (_v % MOD + MOD) % MOD;
        }

        ModInt add(ModInt r) {
            return new ModInt((v + r.v) % MOD);
        }

        ModInt subtract(ModInt r) {
            return new ModInt((v + MOD - r.v) % MOD);
        }

        ModInt multiply(ModInt r) {
            return new ModInt((v * r.v) % MOD);
        }

        ModInt divide(ModInt r) {
            return multiply(r.inverse());
        }

        ModInt inverse() {
            return pow(MOD - 2);
        }

        ModInt pow(long n) {
            ModInt x = this, r = new ModInt(1);
            while (n > 0) {
                if ((n & 1) == 1) r = r.multiply(x);
                x = x.multiply(x);
                n >>= 1;
            }
            return r;
        }

        @Override
        public String toString() {
            return Long.toString(v);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int n = Integer.parseInt(br.readLine());

        ModInt[][] mat = new ModInt[n][n];
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                int x = Integer.parseInt(st.nextToken());
                mat[i][j] = new ModInt(x) / new ModInt(100);
            }
        }

        List<Pair<List<Integer>, ModInt>> sts = new ArrayList<>();
        sts.add(new Pair<>(new ArrayList<>(), new ModInt(1)));

        for (int ph = 0; ph < n; ph++) {
            List<Pair<List<Integer>, ModInt>> nsts = new ArrayList<>();
            for (int f = 1; f < (1 << n); f++) {
                ModInt freq = new ModInt(1);
                for (int i = 0; i < n; i++) {
                    if (((f >> i) & 1) == 1) {
                        freq = freq.multiply(mat[ph][i]);
                    } else {
                        freq = freq.multiply(new ModInt(1).subtract(mat[ph][i]));
                    }
                }
                for (Pair<List<Integer>, ModInt> st : sts) {
                    List<Integer> nst = new ArrayList<>();
                    for (int d : st.getKey()) {
                        for (int i = 0; i < n; i++) {
                            if (((d >> i) & 1) == 1) continue;
                            if (((f >> i) & 1) == 1) continue;
                            nst.add(d ^ (1 << i));
                        }
                    }
                    if (nst.isEmpty()) continue;
                    Collections.sort(nst);
                    nst = removeDuplicates(nst);
                    nsts.add(new Pair<>(nst, st.getValue().multiply(freq)));
                }
            }
            Collections.sort(nsts, (l, r) -> l.getKey().compareTo(r.getKey()));
            sts.clear();
            for (Pair<List<Integer>, ModInt> st : nsts) {
                if (!sts.isEmpty() && sts.get(sts.size() - 1).getKey().equals(st.getKey())) {
                    sts.get(sts.size() - 1).setValue(sts.get(sts.size() - 1).getValue().add(st.getValue()));
                } else {
                    sts.add(st);
                }
            }
            //System.out.println(ph + " " + nsts.size());
        }

        ModInt ans = sts.isEmpty() ? new ModInt(0) : sts.get(0).getValue();

        pw.println(ans);
        pw.close();
    }

    public static List<Integer> removeDuplicates(List<Integer> list) {
        List<Integer> result = new ArrayList<>();
        for (Integer i : list) {
            if (!result.contains(i)) {
                result.add(i);
            }
        }
        return result;
    }

    static class Pair<F, S> {
        F key;
        S value;

        public Pair(F key, S value) {
            this.key = key;
            this.value = value;
        }

        public F getKey() {
            return key;
        }

        public S getValue() {
            return value;
        }

        public void setValue(S value) {
            this.value = value;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Pair<?, ?> pair = (Pair<?, ?>) o;
            return key.equals(pair.key) && value.equals(pair.value);
        }

        @Override
        public int hashCode() {
            return Objects.hash(key, value);
        }
    }
}

