import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.Map;
import java.util.StringTokenizer;

public class Main {
    static final int MOD = 1000000007;
    static final int MAXN = 10;
    static final int MAXM = 70010;
    static final int MAXK = 128;

    static int add(int a, int b) {
        if ((a += b) >= MOD) a -= MOD;
        return a;
    }

    static int mult(int a, int b) {
        long t = 1L * a * b;
        if (t >= MOD) t %= MOD;
        return (int) t;
    }

    static int dec(int a, int b) {
        if ((a -= b) < 0) a += MOD;
        return a;
    }

    static int power(int a, int b) {
        int out = 1;
        while (b > 0) {
            if (b % 2 == 1) out = mult(out, a);
            a = mult(a, a);
            b >>= 1;
        }
        return out;
    }

    static int lowbit(int x) {
        return x & (-x);
    }

    static int dfs(int[] ch, int[] id, int[] q, int[] dp, int[] a, int n, int s, int i) {
        if (id[s] != 0) return id[s];
        id[s] = i;
        for (int j = 0; j < (1 << n); j++) {
            int[] tmp = new int[MAXK];
            System.arraycopy(s, 0, tmp, 0, MAXK);
            for (int k = 0; k < (1 << n); k++) {
                if (tmp[k] == 0) {
                    int x = j & k;
                    while (x > 0) {
                        int t = lowbit(x);
                        if (s[k ^ t] == 1) {
                            tmp[k] = 1;
                            break;
                        }
                        x -= t;
                    }
                }
            }
            ch[i][j] = dfs(ch, id, q, dp, a, n, tmp, i + 1);
        }
        return id[s];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int[][] a = new int[MAXN][MAXN];
        int[][] ch = new int[MAXM][MAXK];
        int[] id = new int[MAXM];
        int[] q = new int[MAXN][1 << MAXN];
        int[][] dp = new int[MAXN][MAXM];
        Map<String, Integer> idMap = new HashMap<>();
        dfs(ch, id, q, dp, a, n, new int[MAXK], 1);
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                a[i][j] = Integer.parseInt(st.nextToken());
                a[i][j] = mult(a[i][j], power(100, MOD - 2));
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << n); j++) {
                q[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    if ((j >> k & 1) == 1) q[i][j] = mult(q[i][j], a[i][k]);
                    else q[i][j] = mult(q[i][j], dec(1, a[i][k]));
                }
            }
        }
        dp[0][1] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= id[1]; j++) {
                for (int k = 0; k < (1 << n); k++) {
                    dp[i][ch[j][k]] = add(dp[i][ch[j][k]], mult(dp[i - 1][j], q[i - 1][k]));
                }
            }
        }
        String bt = "";
        for (int i = 0; i < (1 << n); i++) bt += "1";
        out.println(dp[n][idMap.get(bt)]);
        out.close();
    }
}

