import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007;
    static final int MAX_N = 7;

    static long add(long x, long y) {
        return (x + y) % MOD;
    }

    static long sub(long x, long y) {
        x -= y;
        return (x < 0 ? x + MOD : x);
    }

    static long mult(long x, long y) {
        return (x * y) % MOD;
    }

    static long modpow(long x, long p) {
        if (p == 0) return 1;
        if (p % 2 == 1) return mult(x, modpow(x, p - 1));
        return modpow(mult(x, x), p / 2);
    }

    static long modinv(long x) {
        return modpow(x, MOD - 2);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);

        int n = Integer.parseInt(br.readLine());
        long[][][] T = new long[MAX_N][1 << MAX_N][1 << MAX_N];
        Map<Long, Long>[] DP = new Map[n + 1];
        for (int i = 0; i <= n; i++) {
            DP[i] = new HashMap<>();
        }
        int[] family = new int[1 << MAX_N];
        int[] family_id = new int[1 << MAX_N];
        List<List<Integer>> family_mask = new ArrayList<>(n + 1);

        for (int i = 0; i <= n; i++) {
            family_mask.add(new ArrayList<>());
        }

        for (int mask = 1; mask < (1 << n); mask++) {
            family[mask] = family[mask >> 1] + (mask & 1);
        }

        for (int mask = 0; mask < (1 << n); mask++) {
            family_id[mask] = family_mask[family[mask]].size();
            family_mask.get(family[mask]).add(mask);
        }

        for (int k = 0; k <= n; k++) {
            for (int i = 0; i < family_mask.get(k).size(); i++) {
                int cm = family_mask.get(k).get(i);
                for (int mask = 0; mask < (1 << n); mask++) {
                    long ans = 0;
                    if ((mask & cm) == mask) continue;
                    for (int x = 0; x < n; x++) {
                        if (cm << x) continue;
                        if ((mask & (1 << x)) == 0) continue;
                        int newmask = cm | (1 << x);
                        ans |= 1L << family_id[newmask];
                    }
                    T[k][i][mask] = ans;
                }
            }
        }

        long[][] A = new long[n][n];
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                A[i][j] = Long.parseLong(st.nextToken());
                A[i][j] = mult(A[i][j], modinv(100));
            }
        }

        calc(T, family, family_id, family_mask, A, DP, n);

        pw.println(DP[n].get(1));

        pw.close();
    }

    static void calc(long[][][] T, int[] family, int[] family_id, List<List<Integer>> family_mask, long[][] A, Map<Long, Long>[] DP, int n) {
        for (int k = 0; k < n; k++) {
            for (int edges = 0; edges < (1 << n); edges++) {
                long prob = 1;
                for (int i = 0; i < n; i++) {
                    if (edges << i) prob = mult(prob, A[k][i]);
                    else prob = mult(prob, sub(1, A[k][i]));
                }
                for (Map.Entry<Long, Long> S : DP[k].entrySet()) {
                    long mask = S.getKey();
                    long newmask = 0;
                    long p = mult(prob, S.getValue());
                    for (int i = 0; i < family_mask.get(k).size(); i++) {
                        if (mask << i) {
                            newmask |= T[k][i][edges];
                        }
                    }
                    if (newmask != 0) DP[k + 1].put(newmask, add(DP[k + 1].getOrDefault(newmask, 0L), p));
                }
            }
        }
    }

