import java.io.*;
import java.util.*;

public class Main {
    static final int mod = 1000000007;
    static final int NN = 128;
    static long[][] p = new long[NN][NN];
    static long[][] pro = new long[NN][1 << NN];
    static int[] bpt = new int[1 << NN];
    static long[][] q = new long[NN][NN];
    static int n;
    static int[] id = new int[1 << NN];
    static List<Integer>[] vec = new List[NN];
    static Map<Pair, Integer> mp = new HashMap<>();

    static class Pair {
        int first;
        long second;

        public Pair(int first, long second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Pair pair = (Pair) o;
            return first == pair.first && second == pair.second;
        }

        @Override
        public int hashCode() {
            return Objects.hash(first, second);
        }
    }

    static void add(long[] u, int v) {
        u[0] += v;
        if (u[0] >= mod) u[0] -= mod;
    }

    static int calc(int now, long st) {
        if (st == 0) return 0;
        if (now == n) return 1;
        if (mp.containsKey(new Pair(now, st))) return mp.get(new Pair(now, st));
        int ans = 0;
        for (int j = 1; j < (1 << n); j++) {
            long nst = 0;
            for (int k = 0; k < vec[now].size(); k++) {
                if ((st & (1L << k)) == 0) continue;
                int cur = vec[now].get(k);
                int nxt = j - (j & cur);
                nst |= q[cur][nxt];
            }
            add(new long[]{ans}, pro[now][j] * calc(now + 1, nst) % mod);
        }
        return mp.put(new Pair(now, st), (int) ans);
    }

    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        n = scanner.nextInt();
        long r100 = power(100, mod - 2, mod);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                p[i][j] = scanner.nextLong() * r100 % mod;
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << n); j++) {
                pro[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    if ((j >> k & 1) == 1) {
                        pro[i][j] = pro[i][j] * p[i][k] % mod;
                    } else {
                        pro[i][j] = pro[i][j] * (mod + 1 - p[i][k]) % mod;
                    }
                }
            }
        }

        for (int i = 0; i < (1 << n); i++) {
            bpt[i] = Integer.bitCount(i);
            vec[bpt[i]] = new ArrayList<>();
            id[i] = vec[bpt[i]].size() - 1;
            vec[bpt[i]].add(i);
        }
        for (int i = 0; i < (1 << n); i++) {
            for (int j = 0; j < n; j++) {
                if ((i >> j & 1) == 0) {
                    q[i][1 << j] = 1L << id[i | (1 << j)];
                }
            }
            for (int j = 0; j < (1 << n); j++) {
                q[i][j] = q[i][j & -j] | q[i][j ^ (j & -j)];
            }
        }
        writer.println(calc(0, 1));
        writer.close();
    }

    static long power(long a, long n, long mod) {
        long ans = 1;
        for (; n > 0; n >>= 1, a = a * a % mod) {
            if (n % 2 == 1) {
                ans = ans * a % mod;
            }
        }
        return ans;
    }
}

