                    ans = ans * a[i];
                }
                ans = ans * shift[k - 1];
                ans = ans * tmp;
                ans = ans * shift[x - 1];
                return ans;
            }
        }

        System.out.println(1 / 0);
        return new Matrix(k + 1, -800);
    }

