        val[0] = 1;

        int last = 60;
        for (int i = 1; i < 60; i++) {
            if (val[i - 1] >= 2e18 / k) {
                val[i] = (int) 2e18;
                last = i;
                break;
            } else {
                val[i] = val[i - 1] * k;
            }
        }

