            for(int i = 0; i < d; i++) {
                if(mark[i] && !nd.mark[i]) {
                    for(int j = 0; j <= d; j++)
                        cnt[i][j] = dp[i][j];
                }
                if(!mark[i] && nd.mark[i]) { 
                    for(int j = 0; j <= d; j++)
                        cnt[j][i] = nd.dp[j][i];
                }
                mark[i] |= nd.mark[i];
            }
            for(int i = 0; i <= d; i++)
                for(int j = 0; j <= d; j++)
                    dp[i][j] = cnt[i][j];
        }
        void clean() {
            for(int i = 0; i <= d; i++)
                for(int j = 0; j <= d; j++)
                    dp[i][j] = cnt[i][j] = 0;
        }
        void shift(int x) {
            for(int i = 0; i <= d; i++)
                for(int j = 0; j <= d; j++)
                    cnt[i][j] = 0;
            for(int i = 0; i < d; i++) {
                for(int j = 0; j < d; j++) 
                    cnt[(i + x) % d][(j + x) % d] = dp[i][j];	
                cnt[(i + x) % d][d] = dp[i][d];
            }
            for(int i = 0; i < d; i++)
                cnt[d][(i + x) % d] = dp[d][i];
            cnt[d][d] = dp[d][d];
            for(int i = 0; i <= d; i++)
                for(int j = 0; j <= d; j++)
                    dp[i][j] = cnt[i][j];
            for(int i = 0; i < d; i++)
                tark[i] = mark[(i + x) % d];
            for(int i = 0; i < d; i++)
                mark[i] = tark[i];
        }
    }
    static Node[] md = new Node[lg + 5], hp = new Node[lg + 5], ht;
    static int d;
    static int get(int x) {
        int h = x, pw = 1, t = -1;
        while(h >= d)
            h /= d, pw *= d, t++;
        x %= pw;
        if(t == -1) 
            return hp[h].dp[d][d];
        Node ans = md[t];
        ht = md[t];
        for(int i = 1; i < h; i++) {
            ht.shift(1);
            ans.merge(ht);
        }
        ht = get(x);
        ht.shift(h);	
        ans.merge(ht);
        return ans.dp[d][d];
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        d = Integer.parseInt(st.nextToken());
        n--;
        ArrayList<Integer> v = new ArrayList<>();
        while(n > 0) {
            v.add(n % d);
            n /= d;
        }
        hp[0].dp[d][d] = 2;
        hp[0].dp[d][0] = -1;
        hp[0].dp[0][d] = 1;
        hp[0].mark[0] = true;
        md[0] = hp[0];
        for(int i = 1; i < d; i++) {
            hp[i].dp[d][d] = 2;
            hp[i].dp[d][i] = -1;
            hp[i].dp[i][d] = 1;
            hp[i].mark[i] = true;
            md[0].merge(hp[i]);
            hp[i] = md[0];
        }
        for(int i = 1; i <= v.size(); i++) {
            md[i] = md[i - 1];
            ht = md[i - 1];
            for(int j = 1; j < d; j++) {
                ht.shift(1);
                md[i].merge(ht);
            }
        }
        pw.println(get(n));
        pw.close();
    }
}

