public class Main {
    static final int N = 65;
    static final int mod = (int) 1e9 + 7;
    static int m, len;
    static long n;
    static long[] v = new long[N];

    static class Node {
        long[][] v = new long[35][35];

        public Node() {
            for (int i = 0; i <= 35; i++) {
                for (int j = 0; j <= 35; j++) {
                    v[i][j] = 0;
                }
            }
        }
    }

    static Node[] S = new Node[N][35];
    static Node[] T = new Node[N][35];
    static Node[] s1 = new Node[N][35];
    static Node[] s2 = new Node[N][35];

    static Node multiply(Node a, Node b) {
        Node c = new Node();
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; k <= m; k++) {
                    c.v[i][j] = (c.v[i][j] + (a.v[i][k] * b.v[k][j]) % mod) % mod;
                }
            }
        }
        return c;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        m = sc.nextInt();
        v[0] = n;
        len = 1;
        while (v[len - 1] > 0) {
            v[len] = v[len - 1] / m;
            v[len - 1] %= m;
            len++;
        }
        for (int i = 0; i < len; i++) {
            if (i == 0) {
                for (int j = 0; j < m; j++) {
                    T[i][j] = new Node();
                    T[i][j].v[m][m] = 1;
                    for (int a = 0; a < m; a++) {
                        if (a != j) {
                            T[i][j].v[a][a] = 1;
                            continue;
                        }
                        for (int b = 0; b <= m; b++) {
                            T[i][j].v[a][b] = 1;
                        }
                    }
                }
            } else {
                for (int j = 0; j < m; j++) {
                    if (j == 0) {
                        T[i][j] = s2[i - 1][0];
                    } else {
                        T[i][j] = multiply(s2[i - 1][j], s1[i - 1][j - 1]);
                    }
                }
            }
            s1[i][0] = T[i][0];
            for (int j = 1; j < m; j++) {
                s1[i][j] = multiply(s1[i][j - 1], T[i][j]);
            }
            s2[i][m - 1] = T[i][m - 1];
            for (int j = m - 2; j >= 0; j--) {
                s2[i][j] = multiply(T[i][j], s2[i][j + 1]);
            }
        }
        Node S = new Node();
        for (int i = 0; i <= m; i++) {
            S.v[0][i] = 1;
        }
        for (int i = len - 1, j = 0; i >= 0; i--) {
            while (v[i]-- > 0) {
                S = multiply(S, T[i][j]);
                j = (j + 1) % m;
            }
        }
        System.out.println(S.v[0][m]);
    }
}

