import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    static final int mod = (int) 1e9 + 7;
    static final int MAX = 100;

    static int sum(int a, int b) {
        int s = a + b;
        if (s >= mod) s -= mod;
        return s;
    }

    static int sub(int a, int b) {
        int s = a - b;
        if (s < 0) s += mod;
        return s;
    }

    static int mult(int a, int b) {
        return (int) ((long) a * b % mod);
    }

    static int[][] matrixMult(int[][] a, int[][] b) {
        int[][] c = new int[a.length][a.length];
        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < a.length; j++) {
                for (int t = 0; t < a.length; t++) {
                    c[i][t] = sum(c[i][t], mult(a[i][j], b[j][t]));
                }
            }
        }
        return c;
    }

    static int[][] shiftBy1(int[][] mat) {
        int[][] c = new int[mat.length][mat.length];
        for (int i = 0; i < mat.length; i++) {
            for (int j = 0; j < mat.length; j++) {
                int ni = i;
                if (ni < mat.length - 1) ni = (ni + mat.length - 1) % mat.length;
                int nj = j;
                if (nj < mat.length - 1) nj = (nj + mat.length - 1) % mat.length;
                c[i][j] = mat[ni][nj];
            }
        }
        return c;
    }

    static void print(int[][] c) {
        for (int[] t : c) {
            for (int v : t) System.out.print(v + " ");
            System.out.println();
        }
        System.out.println("------------");
    }

    static void init(int n, int k) {
        int digs = 0;
        int cop = n;
        while (cop > 0) {
            cop /= k;
            digs++;
        }
        int[][][] pref = new int[MAX][][];
        for (int i = 0; i < MAX; i++) {
            pref[i] = new int[k + 1][k + 1];
        }
        for (int i = 1; i < k; i++) {
            pref[0][i][i] = 1;
        }
        pref[0][0][k] = 1;
        pref[0][k][0] = mod - 1;
        pref[0][k][k] = 2;
        for (int step = 0; step < digs; step++) {
            for (int i = 1; i <= k - 1; i++) {
                pref[step + 1] = shiftBy1(pref[step]);
                pref[step + 1] = matrixMult(pref[step + 1], pref[step]);
            }
        }
    }

    static int[][] solve(int n, int k) {
        if (n == 0) {
            int[][] c = new int[k + 1][k + 1];
            for (int i = 0; i <= k; i++) {
                c[i][i] = 1;
            }
            return c;
        }
        int dig = 0;
        int pw = 1;
        while (pw <= n / k) {
            pw *= k;
            dig++;
        }
        if (n == pw) return pref[dig];
