        int left = n - steps * pw;
        int[][] curMat = solve(0, k);
        int[][] curCoef = pref[dig];
        for (int i = 0; i < steps; i++) {
            curMat = matrixMult(curMat, curCoef);
            curCoef = shiftBy1(curCoef);
        }
        int[][] otherMat = solve(left, k);
        for (int i = 0; i < steps; i++) {
            otherMat = shiftBy1(otherMat);
        }
        return matrixMult(curMat, otherMat);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        init(n, k);
        int[][] mat = solve(n, k);
        System.out.println(mat[k][k]);
    }
}

