public class Rudy {
    static final int K = 105, Mod = (int) 1e9 + 7;

    static class Matrix {
        int[][] a;

        Matrix() {
            a = new int[K][K];
            for (int i = 0; i < K; i++) {
                for (int j = 0; j < K; j++) {
                    a[i][j] = 0;
                }
            }
        }

        void unit(int len) {
            for (int i = 1; i <= len; i++) {
                a[i][i] = 1;
            }
        }

        void out() {
            for (int i = 1; i <= K; i++) {
                for (int j = 1; j <= K; j++) {
                    System.out.print(a[i][j] + (j == K ? "\n" : " "));
                }
            }
            System.out.println();
        }
    }

    static Matrix move(Matrix base, int step) {
        step %= K;
        Matrix res = new Matrix();
        for (int i = 1; i <= K; i++) {
            for (int j = 1; j <= K; j++) {
                res.a[id(i, step)][id(j, step)] = base.a[i][j];
            }
        }
        return res;
    }

    static int id(int x, int step) {
        return x <= K ? ((x + step - 1) % K + 1) : x;
    }

    static Matrix multiply(Matrix lhs, Matrix rhs) {
        Matrix res = new Matrix();
        int cur = K + 1;
        for (int i = 1; i <= cur; i++) {
            for (int k = 1; k <= cur; k++) {
                if (lhs.a[i][k] != 0) {
                    for (int j = 1; j <= cur; j++) {
                        res.a[i][j] = (res.a[i][j] + (lhs.a[i][k] * rhs.a[k][j]) % Mod) % Mod;
                    }
                }
            }
        }
        return res;
    }

    static Matrix[] A = new Matrix[K];
    static int[] ans = new int[K];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        A[0] = new Matrix();
        A[0].unit(k + 1);
        for (int i = 1; i <= k; i++) {
            A[0].a[1][i] = 1;
        }

        List<Integer> V = new ArrayList<>();
        for (int len = 0; n > 0; V.add(n % k), n /= k) {
            Matrix x = A[len];
            A[++len] = new Matrix();
            A[len].unit(k + 1);
            for (int power = k, p = 0; power > 0; power >>= 1) {
                if (power % 2 == 1) {
                    A[len] = multiply(A[len], move(x, (power ^ 1) << p));
                }
                x = multiply(move(x, 1 << p), x);
                p++;
            }
        }

        int step = 0;
        ans[k + 1] = 1;

        for (int T = V.size() - 1; T >= 0; T--) {
            int cur = V.get(T);
            if (cur > 0) {
                int[] tmp = new int[K];
                for (int times = 0; times < cur - 1; times++) {
                    for (int i = 1; i <= k + 1; i++) {
                        tmp[i] = ans[i];
                        ans[i] = 0;
