public class Main {
    static final int MOD = 1000000007;
    static final long LIM = Long.MAX_VALUE - (long) MOD * MOD;
    static final int MAX_BASE = 32;
    static final int MAX_N = 60;

    static class Mat {
        long[][] data;

        public Mat(int base) {
            data = new long[base + 1][base + 1];
        }

        public void multiply(Mat other, Mat result) {
            for (int i = 0; i <= base; i++) {
                for (int j = 0; j <= base; j++) {
                    long cur = 0;
                    for (int k = 0; k <= base; k++) {
                        if (cur > LIM) cur %= MOD;
                        cur += (long) data[i][k] * other.data[k][j];
                    }
                    result.data[i][j] = cur % MOD;
                }
            }
        }

        public void copy(Mat other) {
            for (int i = 0; i <= base; i++) {
                for (int j = 0; j <= base; j++) {
                    data[i][j] = other.data[i][j];
                }
            }
        }

        public void print() {
            for (int i = 0; i <= base; i++) {
                for (int j = 0; j <= base; j++) {
                    System.out.print(data[i][j] + " ");
                }
                System.out.println();
            }
        }
    }

    public static void main(String[] args) throws IOException {
