        }

        public Matrix multiply(Matrix other) {
            Matrix result = new Matrix(data.length, other.data[0].length);
            for (int i = 0; i < data.length; i++) {
                for (int k = 0; k < other.data.length; k++) {
                    for (int j = 0; j < other.data[0].length; j++) {
