            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    for (int k = 1; k <= n; k++) {
                        add(B.a[i][j], (int) ((long) a[i][k] * rhs.a[k][j] % mod));
                    }
                }
            }
            return B;
        }
