        int[][] v = new int[K][K];

        Matrix() {
            for (int i = 0; i < K; i++) {
                for (int j = 0; j < K; j++) {
                    v[i][j] = 0;
                }
            }
        }

        Matrix multiply(Matrix a) {
            Matrix res = new Matrix();
            for (int k = 0; k < K; k++) {
                for (int i = 0; i < K; i++) {
                    if (v[i][k] != 0) {
                        for (int j = 0; j < K; j++) {
                            if (a.v[k][j] != 0) {
                                res.v[i][j] = (int) ((v[i][k] * 1L * a.v[k][j] + res.v[i][j]) % Mod);
                            }
                        }
                    }
                }
            }
            return res;
        }
    }

    static Matrix[] s = new Matrix[K1];
    static Matrix[] pre = new Matrix[K1];
    static Matrix[] suf = new Matrix[K1];
    static Matrix ans = new Matrix();

    static void work(long n) {
        long tmp = n;
        while (tmp != 0) {
            a[++m] = (int) (tmp % K);
            tmp /= K;
        }
        reverse(a, 1, m);
    }

    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
