            }
        }
        for (int i = 1; i <= m; i++) {
            pre[i - 1] = new Matrix();
            suf[i - 1] = new Matrix();
            pre[i - 1].v[0][0] = s[i - 1][0];
            suf[i - 1].v[K - 1][K - 1] = s[i - 1][K - 1];
            for (int j = 1; j < K; j++) {
                pre[i - 1].v[0][j] = pre[i - 1].v[0][j - 1].multiply(s[i - 1][j]);
            }
            for (int j = K - 2; j >= 0; j--) {
                suf[i - 1].v[j][K - 1] = s[i - 1][j].multiply(suf[i - 1][j + 1]);
            }
            for (int j = 0; j < K; j++) {
                if (j != 0) {
                    s[i].v[j] = suf[i - 1].v[j].multiply(pre[i - 1].v[j - 1]);
                } else {
                    s[i].v[j] = suf[i - 1].v[j];
                }
            }
        }
        for (int i = 0; i < K1; i++) {
            for (int j = 0; j < K; j++) {
                ans.v[j][j] = 1;
                ans.v[i][j] = 1;
