import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    static final int mod = 1000000007;
    static final int N = 33;
    static long[][] bin = new long[N * 2][N];
    static long[][] ans = new long[N][N];
    static long[][] P = new long[N * 2][N];
    static long[][] S = new long[N * 2][N];
    static long[][] A = new long[N * 2][N];
    static int n, m;

    static class Matrix {
        long[][] mat = new long[N][N];

        public Matrix multiply(Matrix a) {
            Matrix res = new Matrix();
            for (int i = 0; i <= m; i++) {
                for (int j = 0; j <= m; j++) {
                    for (int k = 0; k <= m; k++) {
                        res.mat[i][j] = (res.mat[i][j] + mat[i][k] * a.mat[k][j]) % mod;
                    }
                }
            }
            return res;
        }
    }

    static long read() throws IOException {
        long x = 0;
        int f = 1;
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        while (!st.hasMoreTokens()) {
            char ch = (char) System.in.read();
            if (ch < '0' || ch > '9') {
                if (ch == '-') f = -1;
            } else {
                x = x * 10 + ch - '0';
            }
        }
        while (st.hasMoreTokens()) {
            char ch = (char) System.in.read();
            if (ch >= '0' && ch <= '9') {
                x = x * 10 + ch - '0';
            } else {
                break;
            }
        }
        return x * f;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        int n2 = n;
        int len = -1;
        while (n2 > 0) {
            len++;
            bin[len] = n2 % m;
            n2 = n2 / m;
        }
        len++;
        for (int i = 0; i <= m; i++) {
            ans[0][i] = 1;
        }
        for (int i = 0; i < len; i++) {
            for (int j = 0; j <= m; j++) {
                A[i][0].mat[j][j] = 1;
            }
            if (i == 0) {
                for (int j = 0; j < m; j++) {
                    A[i][j].mat[m][m] = 1;
                    for (int k = 0; k < m; k++) {
                        if (k != j) {
                            A[i][j].mat[k][k] = 1;
                            continue;
                        }
                        for (int l = 0; l <= m; l++) {
                            A[i][j].mat[k][l] = 1;
                        }
                    }
                }
            } else {
                for (int j = 0; j < m; j++) {
                    if (j == 0) {
                        A[i][j] = S[i - 1][0];
                    } else {
                        A[i][j] = S[i - 1][j].multiply(P[i - 1][j - 1]);
                    }
                }
            }
            P[i][0] = A[i][0];
            for (int j = 1; j < m; j++) {
                P[i][j] = P[i][j - 1].multiply(A[i][j]);
            }
            S[i][m - 1] = A[i][m - 1];
            for (int j = m - 2; j >= 0; j--) {
                S[i][j] = A[i][j].multiply(S[i][j + 1]);
            }
        }
        int j = 0;
        for (int i = len - 1; i >= 0; i--) {
            while (bin[i] > 0) {
                ans = ans.multiply(A[i][j]);
                j++;
                if (j == m) j = 0;
                bin[i]--;
            }
        }
        PrintWriter out = new PrintWriter(System.out);
        out.println(ans[0][m]);
        out.close();
    }
}

