import java.util.Scanner;
public class Main {
    static int n, k, p;
    static int[] f = new int[26][250010];
    static int[] fac = new int[250010];
    static int[] inv = new int[250010];

    static int fpow(int a, int b) {
        int ans = 1, t = a;
        while (b > 0) {
            if ((b & 1) == 1) ans = (int) ((long) ans * t % p);
            t = (int) ((long) t * t % p);
            b >>= 1;
        }
        return ans;
    }

    static int lowbit(int x) {
        return x & (-x);
    }

    static void init() {
        fac[0] = 1;
        for (int i = 1; i <= n; i++)
            fac[i] = (int) ((long) fac[i - 1] * i % p);
        inv[n] = fpow(fac[n], p - 2);
        for (int i = n; i >= 1; i--)
            inv[i - 1] = (int) ((long) inv[i] * i % p);
        return;
    }

    static int solve(int cur, int S) {
        if (f[cur][S] != -1)
            return f[cur][S];
        if (S == 0) {
            f[cur][S] = fac[n];
            for (int i = 1; i <= cur; i++)
                f[cur][S] = (int) ((long) f[cur][S] * (k - i + 1) % p);
            return f[cur][S];
        }
        f[cur][S] = 0;
        int U = S - lowbit(S);
        for (int T = U; T > 0; T = (T - 1) & U)
            f[cur][S] = (f[cur][S] + (int) ((long) inv[S - T] * solve(cur + 1, T) % p)) % p;
        f[cur][S] = (f[cur][S] + (int) ((long) inv[S] * solve(cur + 1, 0) % p)) % p;
        return f[cur][S];
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        k = scanner.nextInt();
        p = scanner.nextInt();
        int ans = 1;
        for (int i = 1; i <= n; i++)
            ans = (int) ((long) ans * k % p);
        if (n % 2 == 0) {
            init();
            for (int i = 0; i <= n; i++)
                for (int j = 0; j <= n; j++)
                    f[i][j] = -1;
            ans = (ans - solve(0, n) + p) % p;
        }
        System.out.println(ans);
    }
}

