        long res = 1, tp = a;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = (res * tp) % mod;
            }
            tp = (tp * tp) % mod;
            b >>= 1;
        }
        return res;
    }

    static long cal(int a, int b) {
        return (((fac[a] * inv[b]) % mod) * inv[a - b]) % mod;
    }

