public class Main {
    static long mod, dp[][] = new long[18][250005];
    static long fac[] = new long[250005], inv[] = new long[250005];
    static long n, k;

    static long qpow(long a, long b) {
        long res = 1, tp = a;
        while (b > 0) {
            if ((b & 1) > 0) {
                res = (res * tp) % mod;
            }
            tp = (tp * tp) % mod;
            b >>= 1;
        }
        return res;
    }

    static long cal(int a, int b) {
        return (((fac[a] * inv[b]) % mod) * inv[a - b]) % mod;
    }

    static long calc() {
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = (fac[i - 1] * i) % mod;
        }
        inv[n] = qpow(fac[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv[i] = (inv[i + 1] * (i + 1)) % mod;
        }
        for (int i = 1; i <= n; i++) {
            dp[1][i] = inv[i];
        }
        long ans = (dp[1][n] * cal(k, 1)) % mod;
        int t = Math.min(17, (int) k);
        for (int i = 2; i <= t; i++) {
            for (int j = n; j >= 0; j--) {
                for (int l = j; l >= 0; l = (l - 1) & j) {
                    dp[i][j] = (dp[i][j] + (dp[i - 1][j ^ l] * inv[l])) % mod;
                    if (dp[i][j] > 17446744073709551616) {
                        dp[i][j] %= mod;
                    }
                }
            }
            ans = (ans + (dp[i][n] * cal(k, i))) % mod;
        }
        ans = (ans * fac[n]) % mod;
        return ans;
    }

