	p[0]=1;
	fo(i,1,n) {
		p[i]=0;
		fo(j,1,i) p[i]+=h[j]*p[i-j]%Mo*j;
		p[i]=p[i]%Mo*inv[i]%Mo;
	}
	fo(i,0,n) h[i]=p[i];
}

