        fac[0] = 1;
        long ti = Math.max(n, k);
        for (int i = 1; i <= ti; i++) {
            fac[i] = fac[i - 1] * i % mod;
        }
        inv[ti] = pow(fac[ti], mod - 2);
        for (int i = ti - 1; i >= 0; i--) {
            inv[i] = inv[i + 1] * (i + 1) % mod;
        }
        for (int i = 1; i <= n; i++) {
            dp[1][i] = inv[i];
        }
        long ans = dp[1][n] * comb(k, 1) % mod;
        int t = Math.min(18, k);
        for (int i = 2; i <= t; i++) {
            for (int j = n; j >= 0; j = (j - 1) & n) {
                if (dp[i - 1][j] != 0) {
                    int r = n ^ j;
                    for (int l = r; l > j; l = (l - 1) & r) {
                        dp[i][j ^ l] += dp[i - 1][j] * inv[l];
                        if (dp[i][j ^ l] > MOD) {
                            dp[i][j ^ l] %= MOD;
                        }
                    }
                }
            }
            for (int j = n; j >= 0; j = (j - 1) & n) {
