            if (b % 2 == 1) {
                res = res * tp % MOD;
            }
            tp = tp * tp % MOD;
            b >>= 1;
        }
        return res;
    }

    static long comb(int a, int b) {
        return (((fac[a] * inv[b]) % MOD) * inv[a - b]) % MOD;
    }

    static long calc() {
        int i, j, l;
        fac[0] = 1;
