import java.io.*;
import java.util.*;

public class Main {
    static final int N = 300005, M = 100005;
    static final int mod = (int) 1e9 + 7;
    static long[] fac = new long[N], ifac = new long[N];
    static long[][] dp = new long[2][N];

    static long C(int x, int y) {
        return (fac[x] * ifac[x - y] % mod * ifac[y]) % mod;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        fac[0] = ifac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = (fac[i - 1] * i) % mod;
        }
        ifac[n] = pow(fac[n], mod - 2);
        for (int i = n - 1; i >= 1; i--) {
            ifac[i] = (ifac[i + 1] * (i + 1)) % mod;
        }
        if (n % 2 == 1) {
            pw.println(pow(k, n));
            pw.close();
            return;
        }
        long ans = 0;
        dp[0][n] = 1;
        for (int i = 1; i <= k; i++) {
            Arrays.fill(dp[i & 1], 0);
            long res = 0;
            for (int j = 1; j <= n; j++) {
                long tmp = dp[i - 1 & 1][j];
                if (tmp == 0) continue;
                int u = j ^ (j & -j);
                for (int k = u; k > 0; k = (k - 1) & u) {
                    dp[i & 1][k] = (dp[i & 1][k] + tmp * C(j, k)) % mod;
                }
                res = (res + tmp) % mod;
            }
            res = (res * ifac[k - i]) % mod;
            ans = (ans + res) % mod;
        }
        ans = (pow(k, n) - ans + mod) % mod;
        pw.println(ans);
        pw.close();
    }

    static long pow(long x, int y) {
        long ans = 1;
        while (y > 0) {
            if (y % 2 == 1) {
                ans = (ans * x) % mod;
            }
            x = (x * x) % mod;
            y /= 2;
        }
        return ans;
    }
}

