public class Main {
    static final int N = 300010;
    static int P;
    static int[] f = new int[19][N];
    static int[] ifac = new int[N];
    static int[] fac = new int[N];
    static int[] inv = new int[N];

    static long fpow(long a, int b, long c) {
        for (; b > 0; b >>= 1, a = a * a % P) {
            if ((b & 1) == 1) c = c * a % P;
        }
        return c;
    }

    static void init(int n) {
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = (int) (1L * fac[i - 1] * i % P);
        }
        ifac[n] = fpow(fac[n], P - 2);
        for (int i = n - 1; i >= 0; i--) {
            ifac[i] = (int) (ifac[i + 1] * (i + 1) % P);
        }
        inv[1] = 1;
        for (int i = 2; i <= n; i++) {
            inv[i] = (int) (1L * (P - P / i) * inv[P % i] % P);
        }
    }

    static void add(int[] x, int y) {
        x[0] = (x[0] + y) % P;
    }

    static void sub(int[] x, int y) {
        x[0] = (x[0] - y + P) % P;
    }

    static void FMT(int[] f, int n) {
        for (int l = 1; l < n; l <<= 1) {
            for (int i = 0; i < n; i += l << 1) {
                for (int j = 0; j < l; j++) {
                    add(f[i + j + l], f[i + j]);
                }
            }
        }
    }

    static void IFMT(int[] f, int n) {
        for (int l = 1; l < n; l <<= 1) {
            for (int i = 0; i < n; i += l << 1) {
                for (int j = 0; j < l; j++) {
                    sub(f[i + j + l], f[i + j]);
                }
            }
        }
    }

    static int[] ln(int[] f, int[] g, int n) {
        g[0] = 0;
        for (int i = 1; i < n; i++) {
            g[i] = 0;
            for (int j = 1; j < i; j++) {
                g[i] = (g[i] + 1L * f[i - j] * g[j] % P * j) % P;
            }
            g[i] = (f[i] + 1L * g[i] * (P - inv[i])) % P;
        }
        return g;
    }

    static int[] exp(int[] f, int[] g, int n) {
        g[0] = 1;
        for (int i = 1; i < n; i++) {
            g[i] = 0;
            for (int j = 1; j <= i; j++) {
                g[i] = (g[i] + 1L * g[i - j] * f[j] % P * j) % P;
            }
            g[i] = (1L * g[i] * inv[i]) % P;
        }
        return g;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = sc.nextInt();
        int k = sc.nextInt();
        P = sc.nextInt();
        int ans = (int) fpow(k, n);
        if (n % 2 == 0) {
            int m = (int) Math.log(n) / Math.log(2) + 1;
            init(1 << m);
            for (int i = 0; i < (1 << m); i++) {
                f[Integer.bitCount(i)][i] = ifac[i];
            }
            for (int i = 0; i <= m; i++) {
                FMT(f[i], 1 << m);
            }
            int[] F = new int[20];
            int[] G = new int[20];
            for (int i = 0; i < (1 << m); i++) {
                for (int j = 0; j <= m; j++) {
                    F[j] = f[j][i];
                }
                G = ln(F, G, m + 1);
                for (int j = 0; j <= m; j++) {
                    G[j] = 1L * G[j] * k % P;
                }
                exp(G, F, m + 1);
                for (int j = 0; j <= m; j++) {
                    f[j][i] = F[j];
                }
            }
            IFMT(f[Integer.bitCount(n)], 1 << m);
            ans = (P + ans - 1L * f[Integer.bitCount(n)][n] * fac[n] % P) % P;
        }
        out.println(ans);
        out.close();
    }
}

