import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

public class Main {
    static final int N = 262155;
    static final int M = 31;
    static long n, k, mod;
    static int[] jc = new int[N];
    static int[] inv = new int[N];
    static int[] jc2 = new int[N];
    static int[][] dp = new int[N][M];
    static boolean[][] vis = new boolean[N][M];
    static int[] Log = new int[N];

    static int getcnt(int x) {
        int cnt = 0;
        while (x > 1 && x % 2 == 0) {
            ++cnt;
            x /= 2;
        }
        return cnt;
    }

    static int C(int n, int m) {
        return (int) ((long) jc[n] * inv[m] % mod * inv[n - m] % mod);
    }

    static int dfs(int n, int k) {
        if (n == 0) return 1;
        if (k == 0) return 0;
        if (dp[n][k] != -1) {
            return dp[n][k];
        }
        int di = 1 << Log[n];
        int ret = 0;
        for (int i = n; i >= di; i -= 2) {
            ret = (int) (((long) ret + ((long) C(n, i) * dfs(n - i, k - 1)) % mod * k) % mod);
        }
        return dp[n][k] = ret;
    }

    static Queue<Pair> que = new ArrayDeque<>();

    static int bfs(int n, int k) {
        que.add(new Pair(n, k));
        while (!que.isEmpty()) {
            int n1 = que.peek().first, k1 = que.peek().second;
            que.poll();
            if (n1 == 0 || k1 == 0) continue;
            int di = 1 << Log[n1];
            for (int i = n1; i >= di; i -= 2) {
                if (jc2[i] + jc2[n1 - i] == jc2[n1] && !vis[n1 - i][k1 - 1]) {
                    vis[n1 - i][k1 - 1] = true;
                    que.add(new Pair(n1 - i, k1 - 1));
                }
            }
        }
        for (int i = que.size() - 1; i >= 0; --i) {
            int n1 = que.peek().first, k1 = que.peek().second;
            que.poll();
            if (n1 == 0) {
                dp[n1][k1] = 1;
                continue;
            }
            if (k1 == 0) {
                dp[n1][k1] = 0;
                continue;
            }
            int di = 1 << Log[n1];
            for (int i = n1; i >= di; i -= 2) {
                if (jc2[i] + jc2[n1 - i] == jc2[n1])
                    dp[n1][k1] = (int) (((long) dp[n1][k1] + ((long) C(n1, i) * dp[n1 - i][k1 - 1]) % mod * k1) % mod);
            }
        }
        return dp[n][k];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String[] s = br.readLine().split(" ");
        n = Long.parseLong(s[0]);
        k = Long.parseLong(s[1]);
        mod = Long.parseLong(s[2]);
        jc[0] = 1;
        Arrays.fill(vis, false);
        Log[0] = -1;
        for (int i = 1; i <= N; ++i) {
            jc[i] = (int) ((long) jc[i - 1] * i % mod);
            Log[i] = Log[i >> 1] + 1;
            jc2[i] = jc2[i - 1] + getcnt(i);
        }
        inv[N] = ksm(jc[N], mod - 2);
        for (int i = N - 1; i >= 1; --i) {
            inv[i] = (int) ((long) inv[i + 1] * (i + 1) % mod);
        }
        inv[0] = inv[1];
        if (n % 2 == 1) {
            pw.println(ksm(k, n));
        } else {
            int cnt = 0;
            for (int i = 0; i < 62; ++i) {
                if ((n & (1L << i)) != 0) ++cnt;
            }
            int fei = 0, now = 1;
            int ans = (int) (ksm(k, n));
            pw.println(((ans - bfs((int) n, (int) k)) % mod + mod) % mod);
        }
        pw.close();
    }

    static int ksm(int x, long y) {
        int ret = 1;
        while (y > 0) {
            if ((y & 1) != 0) {
                ret = (int) ((long) ret * x % mod);
            }
            x = (int) ((long) x * x % mod);
            y >>= 1;
        }
        return ret;
    }

    static class Pair {
        int first, second;

        public Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }
}

