import java.util.*;

public class Main {
    static final int maxn = 500 + 5;
    static int n, m, mod;
    static long jc[] = new long[maxn << 2];
    static long inv[] = new long[maxn << 2];
    static long f[] = new long[maxn];
    static long g[] = new long[maxn];

    static long upd(long x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void add(long x, long y) {
        x = upd(x + y);
    }

    static long ksm(long x, long k) {
        long ans = 1;
        while (k > 0) {
            if ((k & 1) == 1) ans = (ans * x) % mod;
            x = (x * x) % mod;
            k >>= 1;
        }
        return ans;
    }

    static void init(int n) {
        jc[0] = 1;
        for (int i = 1; i <= n; i++) jc[i] = (jc[i - 1] * i) % mod;
        inv[n] = ksm(jc[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) inv[i] = (inv[i + 1] * (i + 1)) % mod;
    }

    static long C(int n, int m) {
        if (n < 0 || m < 0 || n < m) return 0;
        return (jc[n] * inv[n - m] % mod * inv[m] % mod);
    }

    static long S(int n) {
        return (n * (n + 1)) / 2;
    }

    static long[] operator*(long[] A, long[] B) {
        long[] C = new long[A.length + B.length - 1];
        for (int i = 0; i < A.length; i++) {
            for (int j = 0; j < B.length; j++) {
                add(C[i + j], (A[i] * B[j]) % mod);
            }
        }
        return C;
    }

    static long G(int n, int m) {
        return C(m + n - 1, n - 1);
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int t = 1;
        while (t-- > 0) {
            n = sc.nextInt();
            m = sc.nextInt();
            mod = sc.nextInt();
            init(m << 1);
            f[0] = 1;
            for (int i = 1; i <= n; i++) {
                for (int j = 0; j < i; j++) {
                    add(f[i], (f[j] * f[i - 1 - j] % mod * C(i - 1, j) % mod));
                }
                f[i] = (f[i] * (i + 1)) % mod;
            }
            for (int i = 1; i <= n; i++) {
                for (int j = 0; j < i; j++) {
                    add(g[i], ((2 * f[j] * g[i - 1 - j] % mod * C(i - 1, j) % mod * (i + 1) % mod + C(i - 1, j) * (S(j) + S(i - 1 - j)) % mod * f[j] % mod * f[i - 1 - j] % mod) % mod));
                }
            }
            for (int i = 0; i <= n; i++) {
                g[i] = (g[i] * inv[i]) % mod;
                f[i] = (f[i] * inv[i]) % mod;
            }
            long ans = 0;
            for (int i = 1; i <= m - n + 1; i++) {
                add(ans, (g[n] * G(i + 1, m - n - i + 1) % mod * jc[n] % mod * i % mod));
                g = Arrays.copyOf(g, n + 1);
                g = (g * f);
            }
            pw.println(ans);
        }
        pw.flush();
    }
}

