                pom = (pom * (j + 1)) % P;
                pom = (pom + ile[i - j - 1] * ile[j] * (j * (j + 1) / 2)) % P;
                pom = (pom * dwu[i - 1][j]) % P;
                dp1[i] = (dp1[i] + pom) % P;
                pom = dwu[i - 1][j];
                pom = (pom * ile[j]) % P;
                pom = (pom * ile[i - j - 1]) % P;
                pom = (pom * (j + 1)) % P;
                ile[i] = (ile[i] + pom) % P;
            }
            ile[i] = (ile[i] + ile[i]) % P;
            dp1[i] = (dp1[i] + dp1[i]) % P;
        }
        dp2[0][0] = 1;
        dp3[0][0] = 0;
        for (int i = 1; i <= n + 1; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; k <= m; k++) {
                    if (j + k <= m && i + k + 1 <= n + 1) {
                        long pom = dp2[i - 1][j];
                        pom = (pom * dwu[m - j][k]) % P;
                        pom = (pom * ile[k]) % P;
                        long pom3 = dp3[i - 1][j];
                        pom3 = (pom3 * ile[k]) % P;
                        pom3 = (pom3 + dp1[k] * dp2[i - 1][j]) % P;
                        pom3 = (pom3 * dwu[m - j][k]) % P;
                        dp2[i + k + 1][j + k] = (dp2[i + k + 1][j + k] + pom) % P;
                        dp3[i + k + 1][j + k] = (dp3[i + k + 1][j + k] + pom3) % P;
                    }
                }
            }
        }
        pw.println(dp3[n + 1][m]);
        pw.close();
    }
