import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;
    static final int MAX = 10010;

    static long pow(long a, int n) {
        long res = 1;
        while (n > 0) {
            if (n % 2 == 1) res = res * a % MOD;
            a = a * a % MOD;
            n /= 2;
        }
        return res;
    }

    static long inv(long a) {
        return pow(a, MOD - 2);
    }

    static long fact[] = new long[MAX];
    static long finv[] = new long[MAX];
    static long invs[] = new long[MAX];

    static void initfact() {
        fact[0] = 1;
        for (int i = 1; i < MAX; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        finv[MAX - 1] = inv(fact[MAX - 1]);
        for (int i = MAX - 2; i >= 0; i--) {
            finv[i] = finv[i + 1] * (i + 1) % MOD;
        }
        for (int i = MAX - 1; i >= 1; i--) {
            invs[i] = finv[i] * fact[i - 1] % MOD;
        }
    }

    static long choose(int n, int k) {
        return fact[n] * finv[n - k] % MOD * finv[k] % MOD;
    }

    static long binom(int a, int b) {
        return fact[a + b] * finv[a] % MOD * finv[b] % MOD;
    }

    static long catalan(int n) {
        return binom(n, n) - (n - 1 >= 0 ? binom(n - 1, n + 1) : 0);
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int m = sc.nextInt();
        long mod = sc.nextLong();
        initfact();

        long ans = 0;
        for (int len = 1; len <= m; len++) {
            long f = pow(len + 1, len) * len % MOD * invs[len] % MOD;
            for (int i = 0; i <= m - len; i++) {
                int j = i + len;
                long g = pow(n - len, i) % MOD * invs[i] % MOD;
                long h = (n - j) * pow(n + 1, m - 1 - j) % MOD * fact[j] % MOD;
                ans = (ans + f * g * h) % MOD;
            }
        }
        ans = ans * pow(2, m - 1) % MOD * (n + 1 - m) % MOD;
        out.println(ans);

        out.close();
    }

    static class Scanner {
        BufferedReader br;
        StringTokenizer st;

        public Scanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            eat("");
        }

        public void eat(String s) {
            st = new StringTokenizer(s);
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        public boolean hasNext() {
            while (!st.hasMoreTokens()) {
                String s = nextLine();
                if (s == null)
                    return false;
                eat(s);
            }
            return true;
        }

        public String next() {
            hasNext();
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }

