                x = (x * x) % mod;
                y >>= 1;
            }
            return res;
        }

        long inv(long x) {
            return pw(x, mod - 2);
        }

        long ss(int x) {
            return (long) x * (x + 1) / 2;
        }

        long[][] c = new long[N + 1][N + 1];

        // cnt, sum
        long[][] a = new long[N + 1][2];
        long[][] d = new long[N + 2][N + 1];

        void solve() throws IOException {
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= n; j++) {
                    if (i == 0 || j == 0) {
                        c[i][j] = 1;
                        continue;
                    }
                    c[i][j] = (c[i - 1][j] + c[i][j - 1]) % mod;
                }
            }

            Arrays.fill(a[0], 0);
            a[0][0] = 1;
            for (int i = 1; i <= m; i++) {
                for (int j = 0; j <= i; j++) {
                    long[] cur = new long[2];
                    cur[0] = (a[j][0] * a[i - 1 - j][0] % mod);
                    cur[1] = ((a[j][1] * a[i - 1 - j][0] + a[j][0] * a[i - 1 - j][1]) % mod);
                    cur[1] = (cur[1] * (i + 1) + (ss(j) + ss(i - 1 - j)) * cur[0]) % mod;
                    cur[0] = cur[0] * (i + 1) % mod;
                    cur[0] = cur[0] * c[j][i - 1 - j] % mod;
                    cur[1] = cur[1] * c[j][i - 1 - j] % mod;
                    a[i][0] = (a[i][0] + cur[0]) % mod;
                    a[i][1] = (a[i][1] + cur[1]) % mod;
                }
            }

            Arrays.fill(d[0], 0);
            d[0][0][0] = 1;
            for (int i = 0; i <= n + 1; i++) {
                for (int j = 0; j <= m; j++) {
                    for (int k = 0; k <= Math.min(n - i, m - j); k++) {
                        long[] cur = new long[2];
                        cur[0] = (a[k][0] * d[i][j][0] % mod);
                        cur[1] = ((a[k][1] * d[i][j][0] + a[k][0] * d[i][j][1]) % mod);
                        cur[0] = cur[0] * c[j][k] % mod;
                        cur[1] = cur[1] * c[j][k] % mod;
                        d[i + k + 1][j + k][0] = (d[i + k + 1][j + k][0] + cur[0]) % mod;
                        d[i + k + 1][j + k][1] = (d[i + k + 1][j + k][1] + cur[1]) % mod;
                    }
                }
            }
            ans = d[n + 1][m][1];
        }

        void clear() {
            this.mod = 0;
            this.n = 0;
            this.m = 0;
            Arrays.fill(a, 0);
            Arrays.fill(d, 0);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        bw.setFolded(true);
        bw.setLineLength(80);
