    static long[] dp1 = new long[N + 1];
    static long[][][] dp2 = new long[2][N + 1][N + 1];

    static void add(long &x, long y) {
        x += y;
        if (x >= md) x -= md;
    }

    static long sm(int n) {
        return (long) n * (n + 1) / 2;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);

        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int md = Integer.parseInt(st.nextToken());

        for (int i = 0; i <= m; i++) {
            ch[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                add(ch[i][j], ch[i - 1][j]);
                add(ch[i][j], ch[i - 1][j - 1]);
            }
        }

        dp1[0] = 1;
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                long w = (dp1[j - 1] * dp1[i - j] * ch[i - 1][j - 1]) % md;
                add(dp1[i], w);
                add(dp1[i], (sm(j - 1) + sm(i - j)) * w % md);
                add(dp1[i], dp1[j - 1] * dp1[i - j] * (i + 1) * ch[i - 1][j - 1] % md);
                add(dp1[i], dp1[j - 1] * dp1[i - j] * (i + 1) * ch[i - 1][j - 1] % md);
            }
        }

        dp2[0][0][0] = 1;
        dp2[1][0][0] = 1;
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                for (int ln = 1; ln <= n - i; ln++) {
                    add(dp2[1][i + ln][j], dp2[0][i][j]);
                    add(dp2[1][i + ln][j], dp2[0][i][j]);

                    add(dp2[0][i + ln][j + ln], dp2[1][i][j] * dp1[ln] * ch[j + ln][j] % md);
                    add(dp2[0][i + ln][j + ln], dp2[1][i][j] * dp1[ln] * ch[j + ln][j] % md);
                    add(dp2[0][i + ln][j + ln], dp2[1][i][j] * dp1[ln] * ch[j + ln][j] % md);
                }
            }
        }

        long an = dp2[0][n][m];
        add(an, dp2[1][n][m]);
        pw.println(an);
        pw.close();
    }
}

