public class Main {
    static long mod;
    static long[] fr = new long[100005];
    static long[] infr = new long[100005];
    static long[] inv = new long[100005];
    static pt[] dp = new pt[1005];
    static pt[][] up = new pt[1005][1005];

    static class pt {
        long f, g;

        pt(long f, long g) {
            this.f = f;
            this.g = g;
        }
    }

    static long addmod(long x) {
        return x >= mod ? x % mod : x;
    }

    static long submod(long x) {
        return x < 0 ? x + mod : x;
    }

    static long fpow(long x, long y) {
        long ans = 1;
        while (y > 0) {
            if ((y & 1) == 1) ans = (ans * x) % mod;
            x = (x * x) % mod;
            y /= 2;
        }
        return ans;
    }

    static long F(long x) {
        return (x * (x + 1)) / 2 % mod;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = sc.nextInt();
        int m = sc.nextInt();
        mod = sc.nextInt();
        fr[0] = infr[0] = 1;
        for (int i = 1; i <= 100000; i++) {
            fr[i] = (i * fr[i - 1]) % mod;
            infr[i] = fpow(fr[i], mod - 2);
            inv[i] = fpow(i, mod - 2);
        }
        dp[0] = new pt(1, 0);
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                pt nw = dp[j - 1].multiply(dp[i - j]);
                nw.g = addmod((nw.g * (i + 1)) % mod + (nw.f * addmod(F(j - 1) + F(i - j)) % mod));
                nw.g = (nw.g * inv[i]) % mod;
                nw.f = ((nw.f * (i + 1)) % mod * inv[i]) % mod;
                dp[i] = dp[i].add(nw);
            }
        }
        up[0][0] = new pt(1, 0);
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(i, m); j++) {
                if (i == j) up[i][j] = dp[i];
                for (int k = 0; k <= j && k < i; k++) {
                    up[i][j] = up[i][j].add(dp[k].multiply(up[i - k - 1][j - k]));
                }
            }
        }
        long ans = (up[n][m].g * fr[m]) % mod;
        pw.println(ans);
        pw.close();
    }
}

