public class Main {
    static final int N = 515;
    static final int M = 1000000007;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());

        int c = Integer.parseInt(st.nextToken());
        int p = Integer.parseInt(st.nextToken());
        int mod = Integer.parseInt(st.nextToken());

        int[][] newt = new int[N][N];
        int[][] inv_newt = new int[N][N];

        for (int i = 0; i <= c + 1; i++) {
            newt[i][i] = newt[i][0] = 1;
            for (int j = 1; j < i; j++) {
                newt[i][j] = (newt[i - 1][j] + newt[i - 1][j - 1]) % mod;
            }
        }

        for (int i = 0; i <= c + 1; i++) {
            for (int j = 0; j <= c + 1; j++) {
                inv_newt[i][j] = pow(newt[i][j], mod - 2, mod);
            }
        }

        int ans = f(c, p, mod);
        int sum_e = 0;

        for (int i = 0; i < p; i++) {
            int e = 0;
            for (int w = 0; w < i; w++) {
                int zioms = newt[i - 1][w] * f(w, w, mod) % mod * f(c - w - 1, i - 1 - w, mod) % mod;
                zioms = zioms * pow(spow(c + 1, i - 1), mod - 2, mod) % mod;
                e = (e + w * (w + 1) / 2 * zioms) % mod;
            }
            sum_e = (sum_e + e) % mod;
        }

        pw.println(ans * sum_e % mod);
        pw.close();
    }

    static int f(int c, int p, int mod) {
        return pow(c + 1, p, mod) * (c + 1 - p) % mod;
    }

