        int mod = Integer.parseInt(st.nextToken());

        int[][] c = new int[N][N];
        c[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            c[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % mod;
            }
        }

        int[] f = new int[N];
        f[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                int k = i - j - 1;
                f[i] = (f[i] + 1L * f[j] * f[k] % mod * (i + 1) % mod * c[i - 1][j]) % mod;
                f[i] = (f[i] + 1L * g[j] * f[k] % mod * (i + 1) % mod * c[i - 1][j]) % mod;
                f[i] = (f[i] + 1L * f[j] * g[k] % mod * (i + 1) % mod * c[i - 1][j]) % mod;
                f[i] = (f[i] + 1L * f[j] * f[k] % mod * c[i - 1][j] % mod * ((j * (j + 1) / 2) + (k * (k + 1) / 2))) % mod;
            }
        }

        int[][][] dp = new int[N][N][2];
        dp[0][0][1] = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i + 1; j++) {
                dp[i + 1][j][1] = (dp[i + 1][j][1] + dp[i][j][0] + dp[i][j][1]) % mod;
                for (int k = 0; k <= n - i; k++) {
                    dp[i + k][j + k][0] = (dp[i + k][j + k][0] + 1L * dp[i][j][1] * f[k] % mod * c[j + k][j]) % mod;
                }
            }
        }

        int ans = 0;
        for (int j = 0; j <= n; j++) {
            for (int i = 0; i < j; i++) {
                int rem = m - (j - i + 1);
                if (rem < 0) continue;
                for (int k = 0; k <= rem; k++) {
                    ans = (ans + 1L * g[j - i + 1] * dp[i - 1][k][1] % mod * dp[n - j][rem - k][1] % mod * c[m][rem] % mod * c[rem][k]) % mod;
                }
            }
        }

        pw.println(ans);
        pw.close();
    }

    static int readInt(BufferedReader br) throws IOException {
        int v = 0;
        int f = 1;
        int c = br.read();
        while (!Character.isDigit(c) && c != '-') {
            c = br.read();
        }
        if (c == '-') {
            f = -1;
        } else {
            v = c - '0';
        }
        while (Character.isDigit(c = br.read())) {
            v = (v * 10 + c - '0');
        }
        return v * f;
    }

    static long readLong(BufferedReader br) throws IOException {
        long v = 0;
        long f = 1;
        int c = br.read();
        while (!Character.isDigit(c) && c != '-') {
            c = br.read();
        }
        if (c == '-') {
            f = -1;
        } else {
            v = c - '0';
        }
        while (Character.isDigit(c = br.read())) {
            v = (v * 10 + c - '0');
        }
        return v * f;
    }
}

