		int lcnt = i, rcnt = n - i - 1;
		Res lres = lcnt == 0 ? Res(1, 0) : go2(lcnt);
		Res rres = rcnt == 0 ? Res(1, 0) : go2(rcnt);
		int mways = (lcnt + 1) + (rcnt + 1);
		int msummaddness = calcsum(0, lcnt) + calcsum(0, rcnt);
