	REP(i, ncomp) REPE(j, npers) done1[i][j] = false;
	return go1(0, npers).summaddness;
}

void run() {
	scanf("%d%d%d", &ncomp, &npers, &MOD);
	printf("%d\n", solve());
}

int main() {
	run();
	return 0;
}

