import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    static final int maxN = 66;
    static int r, c, n;
    static char[] s = new char[maxN];
    static long[][] comb = new long[maxN][maxN];
    static int[] cnt_a = new int[maxN];
    static int[] cnt_b = new int[maxN];
    static long[] partial = new long[maxN];
    static long[] partial_zero = new long[maxN];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());

        r = Integer.parseInt(st.nextToken());
        c = Integer.parseInt(st.nextToken());
        s = br.readLine().toCharArray();
        n = 2 * (r + c);

        compute_comb();

        for (int i = 1; i <= n; i++) {
            cnt_a[i] = cnt_a[i - 1] + (s[i - 1] == 'A' ? 1 : 0);
            cnt_b[i] = cnt_b[i - 1] + (s[i - 1] == 'B' ? 1 : 0);
        }

        compute_second_part();
        long sol = compute_first_part();

        pw.println(sol);
        pw.close();
    }

    static void compute_comb() {
        for (int i = 0; i <= n; i++) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; j++)
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
        }
    }

    static long get_difs(int conf, int a_bef, int b_bef) {
        long ans = 0;
        long aux1, aux2;

        for (int i = 0; i < c + 1; i++) {
            if ((conf & (1 << i)) != 0) {
                b_bef++;

                aux1 = comb[b_bef - 1][r - 1];
                aux2 = comb[n - b_bef][r] - comb[a_bef][r];

                ans -= aux1 * aux2;
            } else {
                a_bef++;

                aux1 = comb[a_bef - 1][r - 1];
                aux2 = comb[n - a_bef][r] - comb[b_bef][r];

                ans += aux1 * aux2;
            }
        }

        return ans;
    }

    static boolean check(int conf) {
        for (int i = 0; i < c + 1; i++) {
            if (s[2 * r + c + i] == 'A' && ((conf >> i) & 1) != 0) return false;
            if (s[2 * r + c + i] == 'B' && ((conf >> i) & 1) == 0) return false;
        }

        return true;
    }

    static void compute_second_part() {
        int limit = 1 << (c + 1);
        int a_here, b_here;

        for (int conf = 0; conf < limit; conf++) {
            b_here = Integer.bitCount(conf);
            a_here = c + 1 - b_here;

            if (check(conf))
                partial[a_here] += get_difs(conf, r + c - a_here, r + c - b_here);
            else
                partial_zero[a_here] += get_difs(conf, r + c - a_here, r + c - b_here);
        }

        for (int i = 0; i <= c + 1; i++) {
            Arrays.sort(partial, i, partial.length, (a, b) -> Long.compare(a, b));
            Arrays.sort(partial_zero, i, partial_zero.length, (a, b) -> Long.compare(a, b));
        }
    }

    static long get_coef(int conf) {
        int i, j;

        for (i = 0; i < c + 1; i++)
            if (((conf >> i) & 1) != (conf & 1))
                break;

        for (j = i; j < c + 1; j++) {
            if (s[2 * r - 1 + j] == 'A' && ((conf >> j) & 1) != 0) return 0;
            if (s[2 * r - 1 + j] == 'B' && ((conf >> j) & 1) == 0) return 0;
        }

        int set_a = r - 1 + ((conf & 1) == 0 ? i : 0);
        int set_b = r - 1 + ((conf & 1) == 1 ? i : 0);

        if (set_a < cnt_a[2 * r - 2 + i]) return 0;
        if (set_b < cnt_b[2 * r - 2 + i]) return 0;
        return comb[set_a + set_b - cnt_a[2 * r - 2 + i] - cnt_b[2 * r - 2 + i]][set_a - cnt_a[2 * r - 2 + i]];
    }

    static void upd(long[] ans, long act) {
        if (act < 0) act = -act;

        if (ans[0] < act) return;
        if (ans[0] > act) {
            ans[0] = act;
            ans[1] = 1;
            return;
        }

        ans[1]++;
    }

    static long how_many(long[] data, long val) {
        int it1 = Arrays.binarySearch(data, 0, data.length, val);
        int it2 = Arrays.binarySearch(data, 0, data.length, val + 1);
        return it2 - it1;
    }

    static long compute_first_part() {
        int limit = 1 << (c + 1);
        int a_here, b_here;
        long act, coef, coef2;
        long[] ans = new long[]{1L << 60, 0};

        for (int conf = 0; conf < limit; conf++) {
            b_here = Integer.bitCount(conf);
            a_here = c + 1 - b_here;
            act = get_difs(conf, r - 1, r - 1);

            coef = get_coef(conf);
            int it = Arrays.binarySearch(partial, c + 1 - a_here, partial.length, -act);

            if (it >= 0) {
                if (ans[0] >= Math.abs(partial[c + 1 - a_here][it] + act)) {
                    coef2 = how_many(partial, c + 1 - a_here, partial[c + 1 - a_here][it]);
                    upd(ans, partial[c + 1 - a_here][it] + act);
                }
            }

            if (it > 0) {
                it--;
                if (ans[0] >= Math.abs(partial[c + 1 - a_here][it] + act)) {
                    coef2 = how_many(partial, c + 1 - a_here, partial[c + 1 - a_here][it]);
                    upd(ans, partial[c + 1 - a_here][it] + act);
                }
            }

            coef = 0;
            it = Arrays.binarySearch(partial_zero, c + 1 - a_here, partial_zero.length, -act);

            if (it >= 0) {
                coef2 = how_many(partial, c + 1 - a_here, partial[c + 1 - a_here][it]);
                if (ans[0] >= Math.abs(partial_zero[c + 1 - a_here][it] + act)) {
                    coef2 = how_many(partial_zero, c + 1 - a_here, partial_zero[c + 1 - a_here][it]);
                    upd(ans, partial_zero[c + 1 - a_here][it] + act);
                }
            }

            if (it > 0) {
                it--;
                if (ans[0] >= Math.abs(partial_zero[c + 1 - a_here][it] + act)) {
                    coef2 = how_many(partial_zero, c + 1 - a_here, partial_zero[c + 1 - a_here][it]);
                    upd(ans, partial_zero[c + 1 - a_here][it] + act);
                }
            }
        }

        return ans[1];
    }

import java.util.*;
import java.io.*;

public class Main {
    static long[][] ncr = new long[40][40];
    static long[][] ans = new long[30][30];
    static long[] totalarea = new long[100];
    static long[] blockarea = new long[100];
    static long[] dp = new long[100];
    static long[] bp = new long[100];
    static long bestfreq = 0;
    static long best = 0;
    static long m1 = 0;
    static long m2 = 0;
    static long n = 0;
    static long R = 0;
    static long C = 0;
    static String str = "";

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        R = sc.nextLong();
        C = sc.nextLong();
        str = sc.next();
        n = R + C;
        for (int a = 0; a < 40; a++) {
            for (int b = 0; b < 40; b++) {
                if (b > a) {
                    ncr[a][b] = 0;
                    continue;
                }
                if (b == 0 || b == a) {
                    ncr[a][b] = 1;
                    continue;
                }
                ncr[a][b] = ncr[a - 1][b - 1] + ncr[a - 1][b];
            }
        }
        for (int a = 0; a < n; a++) {
            for (int b = 0; b < n; b++) {
                blockarea[a * n + b] = ncr[a][R - 1] * ncr[b][R - 1];
            }
        }
        for (int a = 0; a <= n; a++) {
            for (int b = 0; b <= n; b++) {
                totalarea[a * (n + 1) + b] = 0;
                if (a == 0 || b == 0) continue;
                totalarea[a * (n + 1) + b] = totalarea[(a - 1) * (n + 1) + b] + totalarea[a * (n + 1) + (b - 1)] - totalarea[(a - 1) * (n + 1) + (b - 1)];
                totalarea[a * (n + 1) + b] += blockarea[(a - 1) * n + (b - 1)];
            }
        }
        int d = Math.min(2 * n - 1, n + R - 3);
        for (int x = 0; x <= n; x++) {
            for (int y = 0; y <= n; y++) {
                dp[x * (n + 1) + y] = new long[(int) totalarea[n * (n + 1) + n]];
                bp[x * (n + 1) + y] = new long[(int) totalarea[n * (n + 1) + n]];
            }
        }
        dp[0][0][0] = 1;
        bp[0][0][0] = 1;
        best = ans[(int) R][(int) C];
        m1 = (-best + totalarea[n * (n + 1) + n]) / 2;
        m2 = totalarea[n * (n + 1) + n] - m1;
        for (int x = 0; x <= n; x++) {
            for (int y = 0; y < n; y++) {
                if (x + y + 1 <= d && str.charAt(x + y) != 'B') {
                    for (int i = 0; i < (int) totalarea[n * (n + 1) + n]; i++) {
                        if (dp[x][y][i] > 0) {
                            dp[x][y + 1][i] += dp[x][y][i];
                        }
                    }
                }
                if (x + y + 1 <= 2 * n - d && str.charAt(n - x + n - y - 1) != 'B') {
                    for (int i = 0; i < (int) totalarea[n * (n + 1) + n]; i++) {
                        if (bp[x][y][i] > 0) {
                            bp[x][y + 1][i] += bp[x][y][i];
                        }
                    }
                }
            }
            if (x == n) continue;
            for (int y = 0; y <= n; y++) {
                if (x + y + 1 <= d && str.charAt(x + y) != 'A') {
                    long newarea = totalarea[(x + 1) * (n + 1) + y] - totalarea[x * (n + 1) + y];
                    for (int i = 0; i < (int) totalarea[n * (n + 1) + n]; i++) {
                        if (dp[x][y][i] > 0) {
                            dp[x + 1][y][i + (int) newarea] += dp[x][y][i];
                        }
                    }
                }
                if (x + y + 1 <= 2 * n - d && str.charAt(n - x + n - y - 1) != 'A') {
                    long newarea2 = totalarea[n - x][n - y] - totalarea[n - x - 1][n - y];
                    for (int i = 0; i < (int) totalarea[n * (n + 1) + n]; i++) {
                        if (bp[x][y][i] > 0) {
                            bp[x + 1][y][i + (int) newarea2] += bp[x][y][i];
                        }
                    }
                }
                if (x + y + 1 <= d) {
                    for (int i = 0; i < (int) totalarea[n * (n + 1) + n]; i++) {
                        dp[x][y][i] = 0;
                    }
                }
                if (x + y + 1 <= 2 * n - d) {
                    for (int i = 0; i < (int) totalarea[n * (n + 1) + n]; i++) {
                        bp[x][y][i] = 0;
                    }
                }
            }
        }
        for (int x = 0; x <= n; x++) {
            int y = (int) (d - x);
            if (y < 0 || y > n) continue;
            for (int i = 0; i < (int) totalarea[n * (n + 1) + n]; i++) {
                if (dp[x][y][i] > 0) {
                    bestfreq += dp[x][y][i] * bp[n - x][n - y][(int) m1 - i];
                    if (m1 != m2) {
                        bestfreq += dp[x][y][i] * bp[n - x][n - y][(int) m2 - i];
                    }
                }
            }
        }
        System.out.println(bestfreq);
    }
}
